insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('d3000000-0000-0000-0000-000000000001', 'mrcp2', '3142e6b3-7508-4a4a-997d-b1c3e5ccbf96',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('d3000000-0000-0000-0000-000000000001', 'A', 'Double her oral hydrocortisone dose as per sick day rules and reassess in 24 hours', false, 'Ruled out because oral sick-day dosing is only appropriate when the patient can reliably absorb oral medication; with ongoing vomiting and haemodynamic compromise, parenteral steroid is required immediately, not oral dose-doubling with delayed review.', 1),
('d3000000-0000-0000-0000-000000000001', 'B', 'Withhold fludrocortisone until the vomiting has settled', false, 'Ruled out because withholding mineralocorticoid is not the priority; sufficiently high-dose hydrocortisone provides adequate mineralocorticoid activity acutely, and the urgent issue is parenteral glucocorticoid replacement and volume resuscitation, not manipulating the fludrocortisone dose.', 2),
('d3000000-0000-0000-0000-000000000001', 'C', 'Give oral hydrocortisone with an antiemetic and observe her at home', false, 'Ruled out because a patient with haemodynamic compromise and an inability to tolerate oral intake needs emergency parenteral treatment and admission, not community management.', 3),
('d3000000-0000-0000-0000-000000000001', 'D', 'Increase the fludrocortisone dose alone without additional hydrocortisone', false, 'Ruled out because glucocorticoid deficiency, not mineralocorticoid deficiency, is the immediately life-threatening problem in a crisis; parenteral hydrocortisone is the critical intervention.', 4),
('d3000000-0000-0000-0000-000000000001', 'E', 'Give IM or IV hydrocortisone 100mg immediately and admit for IV fluid resuscitation and monitoring', true, 'Correct. Vomiting means oral steroids cannot be relied upon to be absorbed, and the clinical picture (tachycardia, hypotension, drowsiness) indicates an evolving Addisonian crisis. Parenteral hydrocortisone should be given immediately, on clinical grounds, without waiting for biochemical confirmation, alongside aggressive IV fluid resuscitation.', 5),
('d3000000-0000-0000-0000-000000000002', 'A', 'Start spironolactone empirically without further confirmatory testing', false, 'Ruled out because a raised ratio alone is not diagnostic; confirmatory testing is required before committing to a diagnosis and long-term management pathway, and to determine whether surgery is a realistic later option.', 1),
('d3000000-0000-0000-0000-000000000002', 'B', 'Proceed directly to adrenal CT, and if a unilateral adenoma is seen, refer for laparoscopic adrenalectomy without adrenal vein sampling', false, 'Ruled out because CT cannot reliably lateralise the source of aldosterone excess — a non-functioning incidentaloma may coexist with bilateral hyperplasia, so operating on CT findings alone risks removing the wrong (or an unnecessary) gland.', 2),
('d3000000-0000-0000-0000-000000000002', 'C', 'Stop all antihypertensive medications and simply repeat the aldosterone:renin ratio', false, 'Ruled out because the interfering agents have already been substituted appropriately; the next step is confirmatory testing of autonomous secretion, not further medication manipulation.', 3),
('d3000000-0000-0000-0000-000000000002', 'D', 'Perform a confirmatory suppression test (e.g. saline infusion test) to demonstrate autonomous aldosterone secretion, then proceed to adrenal CT and, if surgery is being considered, adrenal vein sampling', true, 'Correct. An elevated aldosterone:renin ratio is only a screening result; a confirmatory test showing failure of aldosterone suppression is required before labelling primary hyperaldosteronism. Once confirmed, cross-sectional imaging characterises the adrenal glands, but adrenal vein sampling is needed before unilateral surgery is offered, since CT alone frequently misidentifies the source of excess secretion (non-functioning incidentalomas are common).', 4),
('d3000000-0000-0000-0000-000000000002', 'E', 'Measure plasma free metanephrines to investigate for phaeochromocytoma', false, 'Ruled out because the clinical and biochemical picture (hypertension, hypokalaemia, suppressed renin, elevated aldosterone) points to primary hyperaldosteronism, not phaeochromocytoma.', 5),
('d3000000-0000-0000-0000-000000000003', 'A', 'Start an alpha-blocker (e.g. phenoxybenzamine or doxazosin) at least 1-2 weeks before surgery, adding a beta-blocker only once alpha-blockade is established, with liberal salt/fluid intake', true, 'Correct. Adequate alpha-blockade must be established first to control catecholamine-driven vasoconstriction and allow safe volume expansion; a beta-blocker is added afterwards to control reflex tachycardia. This sequence and adequate duration reduce the risk of intraoperative hypertensive crisis and postoperative hypotension after tumour removal.', 1),
('d3000000-0000-0000-0000-000000000003', 'B', 'Start a beta-blocker first to control the tachycardia, adding an alpha-blocker afterwards', false, 'Ruled out because beta-blockade before adequate alpha-blockade leaves alpha-adrenergic vasoconstriction unopposed, which can precipitate a severe hypertensive crisis.', 2),
('d3000000-0000-0000-0000-000000000003', 'C', 'No preoperative blockade is required provided a laparoscopic approach is used', false, 'Ruled out because preoperative alpha-blockade is required regardless of surgical approach, given the risk of catecholamine surge during tumour handling.', 3),
('d3000000-0000-0000-0000-000000000003', 'D', 'Start alpha- and beta-blockade simultaneously on the same day', false, 'Ruled out because starting beta-blockade before alpha-blockade is established (rather than staggered with alpha-blockade first) risks unopposed alpha-mediated vasoconstriction and hypertensive crisis.', 4),
('d3000000-0000-0000-0000-000000000003', 'E', 'Use an ACE inhibitor as the sole preoperative antihypertensive agent', false, 'Ruled out because ACE inhibitors do not adequately control catecholamine-mediated vasoconstriction; alpha-blockade is the established preoperative strategy.', 5),
('d3000000-0000-0000-0000-000000000004', 'A', 'This indicates surgical failure and mandates immediate repeat surgery', false, 'Ruled out because an undetectable postoperative cortisol is the expected and reassuring finding after successful surgery, not a sign of failure.', 1),
('d3000000-0000-0000-0000-000000000004', 'B', 'This suggests a separate, coincidental diagnosis of primary adrenal insufficiency requiring fludrocortisone as well as hydrocortisone', false, $x$Ruled out because the suppressed axis is a direct, expected consequence of the preceding Cushing's disease and its surgical cure, not primary adrenal disease; fludrocortisone is not required as mineralocorticoid production is preserved.$x$, 2),
('d3000000-0000-0000-0000-000000000004', 'C', 'This is consistent with surgical remission; he should be started on hydrocortisone replacement, with the hypothalamic-pituitary-adrenal axis expected to recover gradually over months to a year', true, 'Correct. An undetectable postoperative cortisol reflects appropriate suppression of the previously autonomous corticotroph adenoma and the surrounding normal corticotrophs, and is a marker of surgical cure. The HPA axis remains suppressed afterwards and requires physiological hydrocortisone replacement, which is weaned gradually as the axis recovers, guided by periodic testing (e.g. short Synacthen test or morning cortisol off treatment).', 3),
('d3000000-0000-0000-0000-000000000004', 'D', 'No glucocorticoid replacement is needed because the tumour causing excess cortisol has been removed', false, 'Ruled out because the normal corticotrophs remain suppressed after prolonged endogenous hypercortisolism, so the patient is glucocorticoid-deficient and requires replacement until the axis recovers.', 4),
('d3000000-0000-0000-0000-000000000004', 'E', $x$This indicates early recurrence of Cushing's disease requiring radiotherapy$x$, false, 'Ruled out because recurrence would present with a rising, not undetectable, cortisol; an undetectable level is the marker of remission, not recurrence.', 5),
('d3000000-0000-0000-0000-000000000005', 'A', 'Continue oral potassium supplementation alone without other changes', false, 'Ruled out because potassium supplementation alone does not address the underlying aldosterone excess driving both the hypokalaemia and hypertension.', 1),
('d3000000-0000-0000-0000-000000000005', 'B', 'Start a mineralocorticoid receptor antagonist (e.g. spironolactone or eplerenone)', true, 'Correct. Mineralocorticoid receptor antagonism directly addresses the pathophysiology of aldosterone excess, correcting hypokalaemia and improving blood pressure control while awaiting definitive surgery, and is the standard interim (and long-term, if surgery is not pursued) medical management of primary hyperaldosteronism.', 2),
('d3000000-0000-0000-0000-000000000005', 'C', 'Start amiloride monotherapy without addressing aldosterone excess directly', false, $x$Ruled out because although amiloride can help with potassium, a mineralocorticoid receptor antagonist is the preferred first-line interim therapy as it directly opposes aldosterone's mechanism of action.$x$, 3),
('d3000000-0000-0000-0000-000000000005', 'D', 'Use an ACE inhibitor as the sole interim treatment while awaiting surgery', false, 'Ruled out because ACE inhibitors are less effective than mineralocorticoid receptor antagonists at controlling the specific pathophysiology of primary hyperaldosteronism.', 4),
('d3000000-0000-0000-0000-000000000005', 'E', 'No interim treatment is needed since surgery in six weeks will be curative', false, 'Ruled out because leaving significant hypertension and hypokalaemia untreated for six weeks pending surgery is inappropriate and carries unnecessary risk.', 5),
('d3000000-0000-0000-0000-000000000006', 'A', 'Switch to dexamethasone, which crosses the placenta more readily, to suppress fetal adrenal androgen production', false, 'Ruled out because dexamethasone is used specifically for prenatal treatment of an at-risk fetus in specialised protocols, not as routine maternal replacement therapy in a mother who already has CAH herself; hydrocortisone is preferred for maternal replacement.', 1),
('d3000000-0000-0000-0000-000000000006', 'B', 'Stop glucocorticoid replacement during pregnancy to avoid fetal exposure', false, 'Ruled out because stopping replacement in a glucocorticoid-deficient mother risks maternal adrenal insufficiency, which is dangerous in pregnancy; hydrocortisone should be continued.', 2),
('d3000000-0000-0000-0000-000000000006', 'C', 'Titrate hydrocortisone to fully suppress 17-hydroxyprogesterone to the non-pregnant target range', false, 'Ruled out because 17-OHP is not a reliable monitoring marker in pregnancy and aiming for full suppression risks iatrogenic Cushingoid over-treatment; clinical assessment should guide dosing instead.', 3),
('d3000000-0000-0000-0000-000000000006', 'D', 'Switch to fludrocortisone alone as the primary replacement agent', false, 'Ruled out because fludrocortisone provides mineralocorticoid, not glucocorticoid, replacement; hydrocortisone remains essential for glucocorticoid and androgen suppression in CAH.', 4),
('d3000000-0000-0000-0000-000000000006', 'E', 'Continue hydrocortisone (which does not cross the placenta), titrating the dose according to clinical androgen status rather than aiming to fully suppress 17-hydroxyprogesterone', true, 'Correct. Hydrocortisone is inactivated by placental 11-beta-hydroxysteroid dehydrogenase type 2 and so does not significantly affect the fetus, making it the appropriate glucocorticoid to continue in a mother with classic CAH. Dosing is guided by maternal clinical status (androgen excess symptoms, blood pressure) rather than aiming for full biochemical suppression of 17-OHP, which would risk maternal over-treatment.', 5),
('d3000000-0000-0000-0000-000000000007', 'A', 'Proceed directly to unilateral adrenalectomy regardless of the absence of comorbidity', false, 'Ruled out because surgery is not routinely indicated for mild autonomous cortisol secretion without associated cardiometabolic comorbidity; it is reserved for more significant biochemical or clinical disease.', 1),
('d3000000-0000-0000-0000-000000000007', 'B', 'Manage conservatively with monitoring for development of cardiometabolic complications (blood pressure, glucose, bone density), as this represents mild autonomous cortisol secretion without an overt Cushingoid phenotype', true, 'Correct. Mild, non-suppressible cortisol on a low-dose dexamethasone test without clinical Cushingoid features is termed mild (or possible) autonomous cortisol secretion. In the absence of associated comorbidities such as hypertension, diabetes or osteoporosis, conservative management with periodic monitoring is appropriate rather than surgery, which is reserved for cases with progressive biochemical abnormality or associated comorbidity attributable to cortisol excess.', 2),
('d3000000-0000-0000-0000-000000000007', 'C', 'Start metyrapone to control cortisol excess', false, 'Ruled out because medical cortisol-lowering therapy is used for significant, symptomatic hypercortisolism, not for mild, asymptomatic biochemical findings managed conservatively.', 3),
('d3000000-0000-0000-0000-000000000007', 'D', 'Repeat imaging alone in three months without any functional follow-up', false, 'Ruled out because functional (biochemical) follow-up assessing for progression to overt cortisol excess and development of comorbidities is required, not imaging alone.', 4),
('d3000000-0000-0000-0000-000000000007', 'E', 'No further follow-up is needed since ACTH is not frankly suppressed', false, 'Ruled out because a non-suppressible cortisol response, even with only low-normal ACTH, still warrants periodic monitoring for progression rather than being dismissed entirely.', 5),
('d3000000-0000-0000-0000-000000000008', 'A', 'Yes — surgery is indicated because her eGFR has fallen below 60 mL/min/1.73m2, meeting one of the recognised criteria for parathyroidectomy in asymptomatic disease despite the T-score not reaching -2.5', true, 'Correct. Guidelines for asymptomatic primary hyperparathyroidism recommend parathyroidectomy if any one of several criteria is met, including reduced eGFR (<60 mL/min/1.73m2), marked hypercalcaemia, significant osteoporosis/fracture, or younger age. Renal impairment alone is sufficient to warrant surgical referral, even without meeting the bone density threshold.', 1),
('d3000000-0000-0000-0000-000000000008', 'B', 'No — surgery is only indicated in symptomatic primary hyperparathyroidism', false, 'Ruled out because well-established criteria justify surgery in selected asymptomatic patients, including this one, based on renal function, calcium level, bone density or age, even without classical symptoms.', 2),
('d3000000-0000-0000-0000-000000000008', 'C', 'No — surgery is only indicated if the T-score is below -2.5', false, 'Ruled out because bone density is only one of several independent criteria for surgery; renal impairment alone, as present here, is sufficient to meet criteria.', 3),
('d3000000-0000-0000-0000-000000000008', 'D', 'No — surgery is only appropriate if the corrected calcium is above 3.0 mmol/L', false, 'Ruled out because calcium markedly above the upper limit of normal is only one of several independent criteria; renal impairment alone also qualifies a patient for surgery.', 4),
('d3000000-0000-0000-0000-000000000008', 'E', 'Conservative management with monitoring and a bisphosphonate is preferred over surgery, as surgery is not curative', false, 'Ruled out because parathyroidectomy is definitive and curative for primary hyperparathyroidism when surgical criteria are met, and is preferred over indefinite medical management in this situation.', 5),
('d3000000-0000-0000-0000-000000000009', 'A', 'Give IV zoledronic acid immediately without prior rehydration', false, 'Ruled out because bisphosphonates should not be given to a volume-depleted patient with significant renal impairment without first correcting hydration status, and zoledronic acid itself is relatively contraindicated at this level of renal impairment.', 1),
('d3000000-0000-0000-0000-000000000009', 'B', 'Use a loop diuretic as first-line therapy to lower calcium', false, 'Ruled out because loop diuretics are no longer recommended as first-line therapy and can worsen volume depletion; rehydration and calcium-lowering therapy (avoiding bisphosphonate here) are the priorities.', 2),
('d3000000-0000-0000-0000-000000000009', 'C', 'Use calcitonin as the sole long-term treatment for his hypercalcaemia', false, 'Ruled out because calcitonin has a rapid but short-lived and modest effect due to tachyphylaxis; it is used as a bridging measure, not sole long-term therapy.', 3),
('d3000000-0000-0000-0000-000000000009', 'D', 'Aggressive IV 0.9% saline rehydration, followed by denosumab once volume-repleted, rather than a bisphosphonate given his significant renal impairment', true, 'Correct. IV fluid rehydration is the essential first step in severe hypercalcaemia of malignancy, correcting volume depletion and improving renal calcium clearance. Bisphosphonates are renally cleared and relatively contraindicated in significant renal impairment; denosumab, a RANK ligand inhibitor, is not renally cleared and is preferred in this setting.', 4),
('d3000000-0000-0000-0000-000000000009', 'E', 'Encourage oral fluids alone, without IV rehydration', false, 'Ruled out because severe symptomatic hypercalcaemia with AKI requires aggressive IV rehydration; oral intake alone is inadequate.', 5),
('d3000000-0000-0000-0000-000000000010', 'A', 'Continue the bisphosphonate unchanged since her bone density has improved substantially', false, 'Ruled out because ongoing bisphosphonate therapy in the presence of a probable atypical femoral fracture increases the risk of a completed fracture; the drug should be stopped and the lesion assessed urgently.', 1),
('d3000000-0000-0000-0000-000000000010', 'B', 'Switch to IV zoledronic acid for more potent antiresorptive effect', false, 'Ruled out because continuing (or intensifying) antiresorptive therapy is inappropriate in the presence of a likely atypical femoral fracture; the bisphosphonate class should be stopped.', 2),
('d3000000-0000-0000-0000-000000000010', 'C', 'Stop the bisphosphonate, advise avoiding weight-bearing on the affected leg, and arrange urgent orthopaedic review for consideration of prophylactic fixation', true, 'Correct. This radiographic appearance is characteristic of an impending atypical femoral fracture, a recognised complication of prolonged bisphosphonate therapy. The bisphosphonate should be stopped, the patient should avoid weight-bearing on the affected leg pending orthopaedic assessment (prophylactic intramedullary fixation is often required to prevent a completed fracture), and further osteoporosis treatment reconsidered given her substantially improved bone density after prolonged therapy.', 3),
('d3000000-0000-0000-0000-000000000010', 'D', 'Regard the radiographic findings as an incidental finding requiring no action', false, 'Ruled out because lateral cortical thickening with a transverse lucency is a recognised radiographic marker of impending atypical femoral fracture and requires urgent action, not reassurance.', 4),
('d3000000-0000-0000-0000-000000000010', 'E', 'Increase the bisphosphonate dose to address ongoing thigh pain presumed due to osteoporosis', false, 'Ruled out because increasing bisphosphonate dose would increase the risk of progression to a completed atypical fracture; the drug should be discontinued.', 5),
('d3000000-0000-0000-0000-000000000011', 'A', 'Oral calcium supplementation alone is sufficient given her symptoms', false, 'Ruled out because symptomatic severe hypocalcaemia (corrected calcium 1.7 mmol/L with tetany) requires urgent IV correction, not oral treatment alone.', 1),
('d3000000-0000-0000-0000-000000000011', 'B', 'Give IV calcium gluconate for symptomatic severe hypocalcaemia, followed by oral calcium carbonate and an active vitamin D analogue such as alfacalcidol or calcitriol', true, 'Correct. Symptomatic severe hypocalcaemia requires IV calcium replacement acutely. Because PTH is deficient (post-surgical hypoparathyroidism), the kidney cannot adequately 1-hydroxylate vitamin D, so an active analogue (alfacalcidol or calcitriol) is needed rather than relying on native vitamin D, alongside oral calcium supplementation.', 2),
('d3000000-0000-0000-0000-000000000011', 'C', 'Use native vitamin D (colecalciferol) rather than an active vitamin D analogue', false, 'Ruled out because in PTH deficiency, renal 1-alpha-hydroxylation of native vitamin D is impaired, so an active analogue (alfacalcidol/calcitriol) is required to be effective.', 3),
('d3000000-0000-0000-0000-000000000011', 'D', 'Withhold treatment as this represents mild, expected post-thyroidectomy hypocalcaemia', false, 'Ruled out because this represents severe, symptomatic hypocalcaemia requiring urgent treatment, not a mild self-limiting finding to be observed.', 4),
('d3000000-0000-0000-0000-000000000011', 'E', 'Give IV magnesium alone without calcium replacement', false, 'Ruled out because although hypomagnesaemia should be corrected if present as it can impair PTH secretion/action, the primary and urgent treatment for symptomatic severe hypocalcaemia is IV calcium.', 5),
('d3000000-0000-0000-0000-000000000012', 'A', 'Treat as osteoporosis with a bisphosphonate as first-line therapy', false, 'Ruled out because bisphosphonates should not be started in unrecognised or untreated osteomalacia, as vitamin D deficiency should be corrected first; bisphosphonates are also not indicated for osteomalacia.', 1),
('d3000000-0000-0000-0000-000000000012', 'B', $x$Treat as Paget's disease with zoledronic acid$x$, false, $x$Ruled out because the pattern of diffuse pain, myopathy, low vitamin D and Looser zones is characteristic of osteomalacia, not Paget's disease (which typically shows focal disease with characteristic imaging and normal calcium/vitamin D).$x$, 2),
('d3000000-0000-0000-0000-000000000012', 'C', 'Treat as primary hyperparathyroidism with referral for parathyroidectomy', false, 'Ruled out because the biochemical picture here (low vitamin D, low-normal calcium) is not consistent with primary hyperparathyroidism, which typically shows elevated or high-normal calcium with elevated PTH.', 3),
('d3000000-0000-0000-0000-000000000012', 'D', 'Investigate the elevated ALP as isolated liver pathology, deferring bone treatment', false, 'Ruled out because the elevated ALP here reflects increased osteoblastic activity from osteomalacia, in keeping with the clinical and radiological picture, and the priority is vitamin D and calcium replacement.', 4),
('d3000000-0000-0000-0000-000000000012', 'E', 'Loading-dose colecalciferol replacement followed by maintenance vitamin D, with calcium supplementation', true, 'Correct. The clinical picture (proximal myopathy, bone pain, low vitamin D, elevated ALP, Looser zones/pseudofractures) is characteristic of osteomalacia due to vitamin D deficiency. Treatment is with a loading regimen of colecalciferol to replete stores, followed by maintenance dosing, with calcium supplementation to ensure adequate substrate for bone mineralisation.', 5),
('d3000000-0000-0000-0000-000000000013', 'A', 'IV zoledronic acid to suppress bone turnover, aiming to improve symptoms, reduce bone vascularity, and improve cardiac output before surgery', true, $x$Correct. Indications for treating Paget's disease include bone pain, high-output cardiac failure related to increased skeletal vascularity, and preparation before surgery on affected bone to reduce operative blood loss. IV zoledronic acid is highly effective at suppressing bone turnover and is the treatment of choice in this scenario.$x$, 1),
('d3000000-0000-0000-0000-000000000013', 'B', $x$No treatment is required as Paget's disease is often asymptomatic$x$, false, 'Ruled out because this patient has clear indications for treatment: significant bone pain, high-output cardiac failure, and planned surgery on Pagetic bone.', 2),
('d3000000-0000-0000-0000-000000000013', 'C', 'Oral NSAIDs alone are sufficient management', false, 'Ruled out because analgesia alone does not address the underlying increased bone turnover driving his pain, cardiac failure and vascularity; a bisphosphonate is required.', 3),
('d3000000-0000-0000-0000-000000000013', 'D', 'Calcitonin is preferred over bisphosphonate therapy as first-line treatment', false, $x$Ruled out because bisphosphonates, particularly IV zoledronic acid, are more effective and are the treatment of choice for Paget's disease; calcitonin is used less commonly, mainly if bisphosphonates are contraindicated.$x$, 4),
('d3000000-0000-0000-0000-000000000013', 'E', $x$Surgery should be delayed indefinitely until Paget's disease is 'cured'$x$, false, $x$Ruled out because Paget's disease is not curable but can be effectively suppressed with bisphosphonate therapy, after which surgery can proceed with reduced perioperative risk.$x$, 5),
('d3000000-0000-0000-0000-000000000014', 'A', 'Primary hyperparathyroidism — refer for parathyroidectomy', false, 'Ruled out because the low urine calcium:creatinine clearance ratio and family pattern of lifelong mild, asymptomatic hypercalcaemia are inconsistent with primary hyperparathyroidism (which typically shows a normal or high ratio), and point instead to FHH, in which surgery is not beneficial.', 1),
('d3000000-0000-0000-0000-000000000014', 'B', 'Malignancy-associated hypercalcaemia — arrange staging CT', false, 'Ruled out because the lifelong, familial, mild and asymptomatic nature of the hypercalcaemia, with a low urine calcium excretion, is inconsistent with malignancy-associated hypercalcaemia.', 2),
('d3000000-0000-0000-0000-000000000014', 'C', 'Vitamin D toxicity — stop any vitamin D supplements', false, 'Ruled out because there is no history given of vitamin D supplementation, and the familial pattern with a low urine calcium:creatinine clearance ratio points to FHH rather than vitamin D toxicity.', 3),
('d3000000-0000-0000-0000-000000000014', 'D', 'Familial hypocalciuric hypercalcaemia (FHH) — reassurance, with no indication for parathyroidectomy', true, 'Correct. The combination of lifelong mild hypercalcaemia, an affected family history, inappropriately normal PTH, and a low urine calcium:creatinine clearance ratio (typically <0.01) is characteristic of familial hypocalciuric hypercalcaemia, caused by inactivating mutations in the calcium-sensing receptor. This is a benign condition, and parathyroidectomy does not correct the underlying receptor defect and is not indicated.', 4),
('d3000000-0000-0000-0000-000000000014', 'E', 'Treat with a bisphosphonate to lower calcium', false, 'Ruled out because FHH is a benign condition with no evidence of increased fracture or complication risk, and does not require calcium-lowering treatment.', 5),
('d3000000-0000-0000-0000-000000000015', 'A', 'Pioglitazone', false, 'Ruled out because thiazolidinediones cause fluid retention and are contraindicated in heart failure.', 1),
('d3000000-0000-0000-0000-000000000015', 'B', 'A DPP-4 inhibitor such as saxagliptin', false, 'Ruled out because saxagliptin has been associated with an increased risk of heart failure hospitalisation in trial data, making it an unfavourable choice in a patient with existing heart failure.', 2),
('d3000000-0000-0000-0000-000000000015', 'C', 'An SGLT2 inhibitor (e.g. dapagliflozin or empagliflozin)', true, 'Correct. SGLT2 inhibitors reduce heart failure hospitalisation and cardiovascular mortality in patients with type 2 diabetes and heart failure with reduced ejection fraction, independent of their glycaemic effect, and are recommended as an additional agent in this setting.', 3),
('d3000000-0000-0000-0000-000000000015', 'D', 'Increase the sulfonylurea dose', false, 'Ruled out because intensifying sulfonylurea therapy does not offer the cardiovascular/heart failure benefit seen with SGLT2 inhibitors, and carries hypoglycaemia risk without addressing his heart failure.', 4),
('d3000000-0000-0000-0000-000000000015', 'E', 'Add basal insulin as the next preferred agent', false, 'Ruled out because insulin is not the preferred next step ahead of an SGLT2 inhibitor in a patient with heart failure, given the specific cardioprotective evidence for SGLT2 inhibitors in this population.', 5),
('d3000000-0000-0000-0000-000000000016', 'A', 'Continue metformin at the same dose', false, 'Ruled out because metformin is contraindicated at this level of renal impairment due to lactic acidosis risk.', 1),
('d3000000-0000-0000-0000-000000000016', 'B', 'Stop all pharmacological therapy and manage with diet alone', false, 'Ruled out because her HbA1c is significantly elevated and she requires active pharmacological management, not withdrawal of all treatment.', 2),
('d3000000-0000-0000-0000-000000000016', 'C', 'Add pioglitazone for additional glycaemic control', false, 'Ruled out because pioglitazone causes fluid retention and is used cautiously if at all in patients with significant renal impairment and associated fluid balance concerns, and does not offer the renal-protective benefit of an SGLT2 inhibitor.', 3),
('d3000000-0000-0000-0000-000000000016', 'D', 'Stop metformin (contraindicated at this eGFR) and consider initiating an SGLT2 inhibitor for its renal-protective effects, with insulin added if further glycaemic control is needed', true, 'Correct. Metformin is contraindicated at an eGFR below approximately 30 mL/min/1.73m2 due to the risk of lactic acidosis. SGLT2 inhibitors have demonstrated renal-protective effects (reducing progression of diabetic kidney disease and proteinuria) and can be continued/initiated down to a low eGFR threshold per current evidence and licensing; insulin can be added as needed for further glycaemic control.', 4),
('d3000000-0000-0000-0000-000000000016', 'E', 'Double the metformin dose to improve glycaemic control', false, 'Ruled out because increasing metformin dose in this setting increases the risk of lactic acidosis and is inappropriate given her eGFR.', 5),
('d3000000-0000-0000-0000-000000000017', 'A', 'Permanently relax her glycaemic targets without offering diabetes technology', false, 'Ruled out because relaxing targets alone, without addressing the underlying pattern with technology such as CGM/closed-loop, is not the recommended modern approach and does not address the root problem as effectively.', 1),
('d3000000-0000-0000-0000-000000000017', 'B', 'Increase her insulin doses to further improve her HbA1c', false, 'Ruled out because increasing insulin doses would worsen, not improve, her hypoglycaemia risk; the priority is to reduce hypoglycaemia, not further lower HbA1c.', 2),
('d3000000-0000-0000-0000-000000000017', 'C', 'Switch her to a twice-daily premixed insulin regimen', false, 'Ruled out because premixed regimens offer less flexibility than basal-bolus/pump therapy and are not the recommended approach to managing recurrent severe hypoglycaemia with impaired awareness.', 3),
('d3000000-0000-0000-0000-000000000017', 'D', 'Refer for islet cell transplantation as the first-line intervention', false, 'Ruled out because islet cell transplantation is reserved for selected patients with severe, refractory problematic hypoglycaemia despite optimised medical and technological therapy, not as a first-line step.', 4),
('d3000000-0000-0000-0000-000000000017', 'E', 'Initiate continuous glucose monitoring, with consideration of an insulin pump or hybrid closed-loop system', true, 'Correct. Recurrent severe hypoglycaemia with impaired awareness is a key indication for continuous glucose monitoring (real-time alerts for falling glucose) and, where available, hybrid closed-loop insulin pump therapy, both of which reduce hypoglycaemia frequency and can help restore awareness over time.', 5),
('d3000000-0000-0000-0000-000000000018', 'A', 'A GLP-1 receptor agonist', true, 'Correct. GLP-1 receptor agonists provide additional glycaemic control, promote significant weight loss, and have demonstrated reduction in major adverse cardiovascular events in patients with type 2 diabetes and established atherosclerotic cardiovascular disease, making them the preferred additional agent in this context.', 1),
('d3000000-0000-0000-0000-000000000018', 'B', 'A sulfonylurea', false, 'Ruled out because sulfonylureas do not offer cardiovascular benefit and carry hypoglycaemia and weight gain risk, making them less favourable than a GLP-1 receptor agonist in this high-risk patient.', 2),
('d3000000-0000-0000-0000-000000000018', 'C', 'Basal insulin as the preferred next step ahead of a GLP-1 receptor agonist', false, 'Ruled out because a GLP-1 receptor agonist is preferred ahead of insulin in this context, given its added cardiovascular and weight benefits, with insulin reserved for if targets remain unmet.', 3),
('d3000000-0000-0000-0000-000000000018', 'D', 'A DPP-4 inhibitor', false, 'Ruled out because DPP-4 inhibitors have a more modest glycaemic effect, cause less weight loss, and lack the demonstrated cardiovascular benefit of GLP-1 receptor agonists in this population; combining a DPP-4 inhibitor with a GLP-1 receptor agonist also offers no additional benefit.', 4),
('d3000000-0000-0000-0000-000000000018', 'E', 'Pioglitazone', false, 'Ruled out because pioglitazone causes weight gain and fluid retention, both undesirable in this obese patient with cardiovascular disease, and lacks the cardiovascular outcome benefit of a GLP-1 receptor agonist.', 5),
('d3000000-0000-0000-0000-000000000019', 'A', 'Reduce her insulin doses due to concern about hypoglycaemia risk', false, 'Ruled out because rising glucose readings reflect increasing insulin resistance in later pregnancy, requiring increased, not decreased, insulin doses.', 1),
('d3000000-0000-0000-0000-000000000019', 'B', 'Progressively increase her insulin doses as pregnancy advances, targeting tighter glucose goals with continuous monitoring', true, 'Correct. Insulin resistance increases progressively through the second and third trimesters due to placental hormones, meaning insulin requirements typically rise substantially as pregnancy progresses. Doses should be increased accordingly to meet the tighter pregnancy-specific glucose targets, with frequent monitoring (ideally continuous glucose monitoring) to guide titration and detect hypoglycaemia.', 2),
('d3000000-0000-0000-0000-000000000019', 'C', 'Switch her to oral metformin only', false, 'Ruled out because switching from insulin to metformin monotherapy is not appropriate management for pre-existing type 1 diabetes in pregnancy, where insulin remains the mainstay of therapy.', 3),
('d3000000-0000-0000-0000-000000000019', 'D', 'Keep her insulin doses unchanged since her HbA1c was previously well-controlled', false, 'Ruled out because insulin requirements change dynamically through pregnancy; a previously good HbA1c does not mean current unchanged doses are appropriate given rising readings.', 4),
('d3000000-0000-0000-0000-000000000019', 'E', 'Stop insulin and manage with dietary modification alone', false, 'Ruled out because type 1 diabetes always requires insulin therapy; stopping insulin would risk diabetic ketoacidosis and is never appropriate management.', 5),
('d3000000-0000-0000-0000-000000000020', 'A', 'Spironolactone as the preferred agent in this context', false, 'Ruled out because although spironolactone lowers albuminuria, it carries higher risks of hyperkalaemia and gynaecomastia and lacks the specific renal and cardiovascular outcome evidence in this population that finerenone has demonstrated.', 1),
('d3000000-0000-0000-0000-000000000020', 'B', 'Stop the ACE inhibitor to reduce hyperkalaemia risk', false, 'Ruled out because his potassium is currently normal, and ACE inhibitors are a cornerstone of renoprotection in diabetic nephropathy that should be continued, not stopped.', 2),
('d3000000-0000-0000-0000-000000000020', 'C', 'Finerenone', true, 'Correct. Finerenone, a non-steroidal mineralocorticoid receptor antagonist, has been shown in large trials to reduce the risk of chronic kidney disease progression and cardiovascular events when added to an ACE inhibitor/ARB and SGLT2 inhibitor in patients with diabetic kidney disease and persistent albuminuria, with a lower risk of hyperkalaemia and gynaecomastia than older steroidal agents.', 3),
('d3000000-0000-0000-0000-000000000020', 'D', 'Add an NSAID for symptomatic relief', false, 'Ruled out because NSAIDs can worsen renal function and are best avoided in patients with diabetic kidney disease.', 4),
('d3000000-0000-0000-0000-000000000020', 'E', 'Increase the SGLT2 inhibitor beyond its licensed maximum dose', false, 'Ruled out because exceeding the licensed dose of an SGLT2 inhibitor does not provide additional benefit and is not standard practice; the addition of a new therapeutic class (finerenone) is the appropriate step.', 5),
('d3000000-0000-0000-0000-000000000021', 'A', 'Continue insulin unchanged, since a diagnosis of type 1 diabetes has already been made', false, 'Ruled out because the clinical and biochemical features here are atypical for type 1 diabetes and warrant reconsideration of the diagnosis, which has significant implications for management.', 1),
('d3000000-0000-0000-0000-000000000021', 'B', 'Increase his insulin doses further to improve control', false, 'Ruled out because escalating insulin does not address the possibility of an alternative diagnosis (MODY) that could be more appropriately and simply managed with a sulfonylurea.', 2),
('d3000000-0000-0000-0000-000000000021', 'C', 'Consider genetic testing for maturity-onset diabetes of the young (e.g. HNF1A mutation), with a trial of switching from insulin to a sulfonylurea if confirmed', true, 'Correct. Absent islet autoantibodies, preserved C-peptide years after diagnosis, lean body habitus, and a strong autosomal-dominant-pattern family history should raise suspicion for MODY. HNF1A-MODY is particularly sensitive to sulfonylureas, which can often replace insulin and achieve better control with a simpler regimen once genetically confirmed.', 3),
('d3000000-0000-0000-0000-000000000021', 'D', 'Relabel him as having type 2 diabetes and start metformin alone', false, 'Ruled out because his lean body habitus, young age at onset and strong family history pattern are more suggestive of monogenic diabetes (MODY) than typical type 2 diabetes; genetic testing should be pursued rather than an assumption of type 2 diabetes.', 4),
('d3000000-0000-0000-0000-000000000021', 'E', 'Assume latent autoimmune diabetes of adulthood (LADA) and continue insulin only', false, 'Ruled out because LADA is characterised by positive islet autoantibodies (typically GAD), which are negative here; the clinical picture instead favours MODY.', 5),
('d3000000-0000-0000-0000-000000000022', 'A', 'Delay starting insulin until the potassium has normalised', false, 'Ruled out because insulin should not be delayed in DKA; delaying treatment prolongs ketogenesis and acidosis, and potassium is managed by omitting it from fluids initially rather than delaying insulin.', 1),
('d3000000-0000-0000-0000-000000000022', 'B', 'Add potassium to the first litre of fluid despite a potassium of 5.8 mmol/L', false, 'Ruled out because adding potassium when the level is already above 5.5 mmol/L risks dangerous hyperkalaemia; potassium should be withheld until the level falls.', 2),
('d3000000-0000-0000-0000-000000000022', 'C', 'Give a bolus dose of intravenous insulin before starting the infusion', false, 'Ruled out because an initial insulin bolus is not part of standard DKA protocols and is not required before starting a fixed-rate insulin infusion.', 3),
('d3000000-0000-0000-0000-000000000022', 'D', 'Withhold IV fluids until the insulin infusion has been running for an hour', false, 'Ruled out because IV fluid resuscitation should be started promptly alongside (or just before) insulin, not withheld.', 4),
('d3000000-0000-0000-0000-000000000022', 'E', 'Start a fixed-rate intravenous insulin infusion alongside IV fluids; potassium is not added to the first fluid bag given her potassium is already above 5.5 mmol/L, but is monitored closely and added once it falls below this threshold', true, 'Correct. A fixed-rate intravenous insulin infusion (typically 0.1 unit/kg/hour) should be started promptly alongside IV fluid resuscitation in DKA. Potassium is not added to initial fluids while serum potassium remains above 5.5 mmol/L, as insulin will drive potassium into cells and hyperkalaemia may worsen if potassium were added now; frequent monitoring is required as potassium typically falls once insulin therapy begins, at which point replacement should be added.', 5),
('d3000000-0000-0000-0000-000000000023', 'A', 'Give subcutaneous rapid-acting insulin with a meal, along with basal insulin, and continue the IV insulin infusion for 1-2 hours after subcutaneous insulin is given before stopping it, to prevent rebound hyperglycaemia or recurrent ketosis', true, 'Correct. DKA resolution criteria have been met (pH and ketones normalised), so transition to subcutaneous insulin can begin, but the IV infusion must be continued for a short overlap period (typically 1-2 hours) after subcutaneous insulin (which needs time to be absorbed and act) has been given, to prevent a gap in insulin coverage that could cause rebound hyperglycaemia or recurrence of ketosis.', 1),
('d3000000-0000-0000-0000-000000000023', 'B', 'Stop the IV insulin infusion immediately once she starts eating and drinking', false, 'Ruled out because stopping IV insulin abruptly without an overlap with subcutaneous insulin risks a gap in insulin action and rebound hyperglycaemia/ketosis.', 2),
('d3000000-0000-0000-0000-000000000023', 'C', 'Stop the IV insulin infusion and start subcutaneous insulin with no overlap period', false, 'Ruled out because an overlap period is essential, as subcutaneous insulin takes time to be absorbed and achieve therapeutic effect.', 3),
('d3000000-0000-0000-0000-000000000023', 'D', 'Continue the IV insulin infusion indefinitely without transitioning to subcutaneous insulin', false, 'Ruled out because once DKA has resolved and the patient is eating and drinking, transition to a subcutaneous regimen (with an appropriate overlap) is the correct next step, not indefinite continuation of IV insulin.', 4),
('d3000000-0000-0000-0000-000000000023', 'E', 'Discharge her once glucose is below 10 mmol/L without arranging a basal insulin plan', false, 'Ruled out because a structured plan including basal insulin must be established with an appropriate transition and overlap before considering discharge, not simply once glucose falls.', 5),
('d3000000-0000-0000-0000-000000000024', 'A', 'Manage identically to DKA, starting a fixed-rate insulin infusion at 0.1 unit/kg/hour immediately', false, 'Ruled out because standard DKA-rate insulin dosing risks too rapid a fall in glucose and osmolality in HHS, increasing the risk of dangerous osmotic complications; a more cautious approach is required.', 1),
('d3000000-0000-0000-0000-000000000024', 'B', 'Cautious rehydration with 0.9% saline as the primary therapy, aiming for a gradual, controlled fall in glucose and osmolality over 24-48 hours, adding low-dose insulin only if ketosis is present or glucose is not falling adequately with fluids alone', true, 'Correct. Hyperosmolar hyperglycaemic state (HHS) is managed differently from DKA: fluid replacement alone often substantially lowers glucose, and rapid correction of the profound hyperosmolality risks dangerous osmotic shifts (including central pontine myelinolysis and cerebral oedema). Insulin is used cautiously and at a lower rate than in DKA, reserved for when ketosis is present or glucose fails to fall adequately with rehydration alone.', 2),
('d3000000-0000-0000-0000-000000000024', 'C', 'Correct glucose rapidly with a bolus dose of intravenous insulin', false, 'Ruled out because rapid correction of glucose/osmolality in HHS is dangerous and insulin boluses are not part of standard management.', 3),
('d3000000-0000-0000-0000-000000000024', 'D', 'Use hypotonic (0.45%) saline as the first-line fluid', false, 'Ruled out because 0.9% saline is the standard first-line fluid in HHS; hypotonic fluids are reserved for specific circumstances (e.g. persistently very high corrected sodium) under specialist guidance, not as routine first-line therapy.', 4),
('d3000000-0000-0000-0000-000000000024', 'E', 'Withhold all fluids until insulin has been commenced', false, 'Ruled out because fluid resuscitation is the primary initial therapy in HHS and should not be delayed pending insulin.', 5),
('d3000000-0000-0000-0000-000000000025', 'A', 'DKA can be excluded because the glucose is not significantly elevated', false, 'Ruled out because euglycaemic DKA is a recognised phenomenon, particularly with SGLT2 inhibitor use, and the diagnosis rests on acidosis and ketosis, not glucose level alone.', 1),
('d3000000-0000-0000-0000-000000000025', 'B', 'Treat as simple gastroenteritis with antiemetics and oral rehydration', false, 'Ruled out because the significant acidosis and ketosis indicate DKA requiring urgent specific treatment, not simple symptomatic management of presumed gastroenteritis.', 2),
('d3000000-0000-0000-0000-000000000025', 'C', 'Continue the SGLT2 inhibitor since his glucose is well controlled', false, 'Ruled out because the SGLT2 inhibitor is the likely precipitant of euglycaemic DKA and must be stopped, regardless of the glucose level.', 3),
('d3000000-0000-0000-0000-000000000025', 'D', 'Euglycaemic diabetic ketoacidosis related to SGLT2 inhibitor use; he should be treated as DKA with IV insulin and dextrose-containing fluids to allow adequate insulin dosing despite the near-normal glucose, and the SGLT2 inhibitor should be stopped', true, 'Correct. SGLT2 inhibitors can cause euglycaemic DKA, where significant ketoacidosis occurs with only mildly elevated or even normal glucose, due to enhanced urinary glucose excretion masking the usual degree of hyperglycaemia. Management follows standard DKA principles (IV insulin to switch off ketogenesis) but requires concurrent dextrose infusion to prevent hypoglycaemia while insulin is given, and the SGLT2 inhibitor must be stopped.', 4),
('d3000000-0000-0000-0000-000000000025', 'E', 'Manage with oral rehydration alone given the modest glucose elevation', false, 'Ruled out because significant acidosis and ketosis require IV insulin and fluid therapy following DKA protocols, not oral rehydration alone.', 5),
('d3000000-0000-0000-0000-000000000026', 'A', 'Wait for the ambulance and IV access before treating him', false, 'Ruled out because severe hypoglycaemia with unconsciousness requires immediate treatment; IM glucagon can and should be given without delay while awaiting further help.', 1),
('d3000000-0000-0000-0000-000000000026', 'B', 'Give oral glucose gel to the unconscious patient', false, 'Ruled out because giving oral treatment to an unconscious patient risks aspiration; a non-oral route (IM glucagon, or IV dextrose once access is available) must be used until he is conscious and able to swallow safely.', 2),
('d3000000-0000-0000-0000-000000000026', 'C', $x$Give a dose of rapid-acting insulin to 'stabilise' him$x$, false, 'Ruled out because insulin would worsen his hypoglycaemia and is contraindicated in this situation.', 3),
('d3000000-0000-0000-0000-000000000026', 'D', 'Observe him without any intervention until he wakes spontaneously', false, 'Ruled out because severe hypoglycaemia with unconsciousness is a medical emergency requiring immediate active treatment, not passive observation.', 4),
('d3000000-0000-0000-0000-000000000026', 'E', 'Administer intramuscular glucagon immediately, followed by oral carbohydrate once he regains consciousness', true, 'Correct. In an unconscious hypoglycaemic patient without immediate IV access, intramuscular glucagon is the appropriate immediate treatment (if available and the patient/carer is trained to give it), mobilising hepatic glycogen stores to raise glucose; oral carbohydrate should follow once he is conscious and able to swallow safely, to prevent recurrence.', 5),
('d3000000-0000-0000-0000-000000000027', 'A', 'Discharge him once glucose normalises after the initial bolus', false, 'Ruled out because sulfonylurea-induced hypoglycaemia can recur for many hours after apparent initial correction, and premature discharge risks a dangerous recurrence at home.', 1),
('d3000000-0000-0000-0000-000000000027', 'B', 'Treat this as a one-off event requiring no further monitoring', false, 'Ruled out because recurrent hypoglycaemia has already been observed, indicating ongoing risk that requires structured monitoring, not dismissal as an isolated event.', 2),
('d3000000-0000-0000-0000-000000000027', 'C', 'Admit for prolonged monitoring with a continuous IV dextrose infusion, considering octreotide if hypoglycaemia remains recurrent despite this, given the long half-life and prolonged insulin-secretagogue effect of sulfonylureas', true, 'Correct. Sulfonylurea-induced hypoglycaemia, especially with long-acting agents like glibenclamide (particularly in the elderly or those with renal impairment), can be severe, prolonged and recurrent, because the drug continues to stimulate endogenous insulin secretion for many hours. Management requires admission for prolonged monitoring with a continuous dextrose infusion (not just a single bolus), and octreotide (which suppresses sulfonylurea-stimulated insulin release) can be used for refractory recurrent hypoglycaemia.', 3),
('d3000000-0000-0000-0000-000000000027', 'D', 'Stop dextrose once the glucose is normal after the first correction, without further infusion', false, 'Ruled out because a single bolus is inadequate given the prolonged action of sulfonylureas; a continuous infusion with monitoring is required to prevent recurrence.', 4),
('d3000000-0000-0000-0000-000000000027', 'E', 'Give repeated doses of glucagon as the sole ongoing strategy', false, 'Ruled out because glucagon relies on adequate hepatic glycogen stores (which become depleted with repeated dosing) and does not address the ongoing sulfonylurea-driven endogenous insulin secretion; IV dextrose infusion (with octreotide if needed) is the appropriate ongoing strategy.', 5),
('d3000000-0000-0000-0000-000000000028', 'A', 'Hypoglycaemia — give further IV dextrose without further evaluation', false, 'Ruled out because this clinical picture (headache, falling GCS, bradycardia) is characteristic of cerebral oedema, not hypoglycaemia, and requires the specific measures for cerebral oedema, not simply more dextrose.', 1),
('d3000000-0000-0000-0000-000000000028', 'B', 'Cerebral oedema — stop or slow IV fluids, give IV mannitol (or hypertonic saline), urgently involve senior/critical care staff, and arrange CT head once stabilised, avoiding over-rapid fluid or osmotic correction', true, 'Correct. Headache, reduced conscious level and bradycardia during DKA treatment (particularly in children and young people) are classic warning signs of cerebral oedema, a rare but life-threatening complication linked to overly rapid fluid administration or osmotic shifts. Immediate management includes slowing/stopping fluids, giving hyperosmolar therapy (mannitol or hypertonic saline), urgent senior and critical care involvement, and neuroimaging once the patient is stabilised — treatment should not be delayed awaiting imaging.', 2),
('d3000000-0000-0000-0000-000000000028', 'C', 'Simply reduce the insulin infusion rate as the sole response', false, 'Ruled out because reducing insulin alone does not address the suspected cerebral oedema, which requires fluid restriction, hyperosmolar therapy and urgent senior involvement.', 3),
('d3000000-0000-0000-0000-000000000028', 'D', 'An anxiety or pain response — reassure the patient only', false, 'Ruled out because these features represent recognised warning signs of a life-threatening complication (cerebral oedema) and must never be dismissed as simple anxiety.', 4),
('d3000000-0000-0000-0000-000000000028', 'E', 'Assume sepsis and increase the rate of IV fluid administration', false, 'Ruled out because increasing fluid administration in this context risks worsening cerebral oedema; fluids should be slowed/stopped, not increased.', 5),
('d3000000-0000-0000-0000-000000000029', 'A', 'Diagnose familial hypercholesterolaemia on clinical grounds (Dutch Lipid Clinic Network criteria), start a high-intensity statin (with ezetimibe if needed to reach target), and arrange cascade testing of first-degree relatives', true, 'Correct. The combination of markedly elevated LDL-cholesterol, tendon xanthomas/xanthelasma, and a strong family history of premature coronary disease meets clinical diagnostic criteria for familial hypercholesterolaemia. High-intensity statin therapy (adding ezetimibe if targets are not met) should be started promptly given his very high lifetime cardiovascular risk, and cascade testing of first-degree relatives is essential to identify other affected family members early.', 1),
('d3000000-0000-0000-0000-000000000029', 'B', 'Manage with lifestyle modification alone initially before considering any medication', false, 'Ruled out because his markedly elevated LDL and clinical features indicate a high lifetime cardiovascular risk warranting prompt pharmacological therapy, not lifestyle measures alone first.', 2),
('d3000000-0000-0000-0000-000000000029', 'C', 'Genetic testing is mandatory before starting statin therapy', false, 'Ruled out because a clinical diagnosis (using validated criteria) is sufficient to justify starting statin therapy without delay; genetic testing is useful to confirm the diagnosis and facilitate cascade testing but should not delay treatment.', 3),
('d3000000-0000-0000-0000-000000000029', 'D', 'Treat with a fibrate as first-line therapy', false, 'Ruled out because statins are first-line therapy for the marked LDL elevation seen in familial hypercholesterolaemia; fibrates are used primarily for hypertriglyceridaemia.', 4),
('d3000000-0000-0000-0000-000000000029', 'E', 'No need to screen his relatives, as this is a sporadic finding', false, 'Ruled out because familial hypercholesterolaemia is an autosomal dominant condition with a 50% risk of transmission to first-degree relatives, making cascade testing essential.', 5),
('d3000000-0000-0000-0000-000000000030', 'A', 'Add a fibrate to further lower LDL', false, 'Ruled out because fibrates predominantly lower triglycerides with only a modest effect on LDL, and combining a fibrate with a statin increases myopathy risk without the additional cardiovascular benefit seen with PCSK9 inhibitor therapy.', 1),
('d3000000-0000-0000-0000-000000000030', 'B', 'Switch to a bile acid sequestrant as monotherapy', false, 'Ruled out because bile acid sequestrants provide a more modest LDL reduction and are not the preferred next step ahead of a PCSK9 inhibitor in a patient with established coronary disease and residual risk.', 2),
('d3000000-0000-0000-0000-000000000030', 'C', 'Increase the statin dose beyond the maximum tolerated/licensed dose', false, 'Ruled out because exceeding the maximum tolerated or licensed statin dose increases adverse effect risk without appreciable additional benefit; a different additional agent is required.', 3),
('d3000000-0000-0000-0000-000000000030', 'D', 'Add a PCSK9 inhibitor (e.g. evolocumab or alirocumab)', true, 'Correct. In patients with established atherosclerotic cardiovascular disease who remain above target LDL despite maximum tolerated statin and ezetimibe, PCSK9 inhibitors provide substantial further LDL lowering and have demonstrated reduction in cardiovascular events, and are the appropriate next step.', 4),
('d3000000-0000-0000-0000-000000000030', 'E', 'Accept the current LDL level as adequate since he is already on two agents', false, 'Ruled out because in secondary prevention, further LDL lowering with additional therapy provides further reduction in cardiovascular risk and should be pursued rather than accepted as adequate.', 5),
('d3000000-0000-0000-0000-000000000031', 'A', 'Start a statin alone as the acute treatment', false, 'Ruled out because statins do not lower triglycerides rapidly or substantially enough to be an effective acute treatment in this setting; insulin infusion is the preferred acute measure.', 1),
('d3000000-0000-0000-0000-000000000031', 'B', 'Commence early high-fat enteral feeding to stimulate lipoprotein lipase', false, 'Ruled out because high-fat feeding would worsen hypertriglyceridaemia; a low-fat approach with initial fasting is appropriate acutely.', 2),
('d3000000-0000-0000-0000-000000000031', 'C', 'Plasmapheresis is mandatory as first-line therapy in this stable patient', false, 'Ruled out because plasmapheresis is generally reserved for patients with organ failure or when insulin infusion/supportive measures are inadequate or contraindicated; it is not first-line in a haemodynamically stable patient without organ failure.', 3),
('d3000000-0000-0000-0000-000000000031', 'D', 'No specific lipid-lowering treatment is needed, only standard pancreatitis supportive care', false, 'Ruled out because actively lowering the markedly elevated triglycerides (via insulin infusion) is an important part of management to reduce ongoing pancreatic injury and prevent early recurrence, not just standard supportive care.', 4),
('d3000000-0000-0000-0000-000000000031', 'E', 'An intravenous insulin infusion (with concurrent dextrose to prevent hypoglycaemia), alongside supportive pancreatitis care and strict fasting/very low-fat diet initially', true, 'Correct. IV insulin infusion accelerates lipoprotein lipase activity and promotes triglyceride clearance, providing an effective and rapid means of lowering severely elevated triglycerides in hypertriglyceridaemia-induced pancreatitis, alongside standard supportive pancreatitis management. Dextrose is co-administered to prevent hypoglycaemia from the insulin infusion.', 5),
('d3000000-0000-0000-0000-000000000032', 'A', 'Familial hypercholesterolaemia', false, 'Ruled out because familial hypercholesterolaemia typically produces a more uniform, isolated marked LDL elevation with tendon xanthomas across affected family members, rather than the variable mixed phenotype described here.', 1),
('d3000000-0000-0000-0000-000000000032', 'B', 'Isolated familial hypertriglyceridaemia', false, 'Ruled out because this patient also has significantly elevated LDL, and family members show variable phenotypes including predominant LDL elevation, which is not typical of isolated hypertriglyceridaemia.', 2),
('d3000000-0000-0000-0000-000000000032', 'C', 'Polygenic hypercholesterolaemia', false, 'Ruled out because polygenic hypercholesterolaemia typically presents with isolated modest LDL elevation without the mixed/variable family phenotype and prominent triglyceride/HDL abnormalities described here.', 3),
('d3000000-0000-0000-0000-000000000032', 'D', 'Familial combined hyperlipidaemia', true, 'Correct. Familial combined hyperlipidaemia is characterised by a variable lipid phenotype within the same family (some members with predominantly raised LDL, others with predominantly raised triglycerides, or a mixed pattern), elevated apolipoprotein B, and a substantially increased risk of premature coronary heart disease, fitting this presentation.', 4),
('d3000000-0000-0000-0000-000000000032', 'E', 'Secondary dyslipidaemia due to hypothyroidism', false, 'Ruled out because there is no clinical suggestion of hypothyroidism here, and the strong, variable-phenotype family history points to a primary genetic mixed dyslipidaemia rather than a secondary cause.', 5),
('d3000000-0000-0000-0000-000000000033', 'A', 'High-intensity statin monotherapy should be sufficient given his age', false, 'Ruled out because homozygous FH typically shows a poor response to statin monotherapy due to minimal functional LDL receptor activity; combination therapy and apheresis are usually required.', 1),
('d3000000-0000-0000-0000-000000000033', 'B', 'A fibrate should be used as the mainstay of treatment', false, 'Ruled out because fibrates provide only modest LDL reduction and are not the mainstay of treatment for the marked LDL elevation seen in homozygous FH.', 2),
('d3000000-0000-0000-0000-000000000033', 'C', 'LDL apheresis, continued alongside maximal pharmacological therapy', true, 'Correct. Homozygous familial hypercholesterolaemia typically results in minimal or absent functional LDL receptor activity, meaning response to oral/injectable lipid-lowering therapy alone (which relies substantially on upregulating LDL receptor activity) is often inadequate. LDL apheresis, which physically removes LDL particles from the circulation, is required in addition to maximal pharmacological therapy to achieve meaningful LDL reduction and reduce cardiovascular risk.', 3),
('d3000000-0000-0000-0000-000000000033', 'D', 'Lifestyle modification alone is sufficient at his age', false, 'Ruled out because homozygous FH carries an extremely high risk of very premature cardiovascular disease, and lifestyle measures alone are markedly insufficient to control LDL to a safe level.', 4),
('d3000000-0000-0000-0000-000000000033', 'E', 'Treatment should be delayed until adulthood', false, 'Ruled out because homozygous FH causes accelerated atherosclerosis from early childhood, and aggressive treatment (including apheresis) should begin as early as possible, not be delayed.', 5),
('d3000000-0000-0000-0000-000000000034', 'A', 'Stop the statin until symptoms and creatine kinase resolve, then consider rechallenge with a lower dose or alternative statin (e.g. low-dose or alternate-day rosuvastatin), or non-statin therapy if intolerance persists', true, 'Correct. A significantly elevated creatine kinase (typically more than several times the upper limit of normal) with significant myalgia warrants stopping the statin to prevent progression to rhabdomyolysis. Once symptoms and CK resolve, a cautious rechallenge with a lower dose or a different statin (which may be better tolerated), or non-statin alternatives such as ezetimibe or a PCSK9 inhibitor, should be considered to maintain cardiovascular risk reduction.', 1),
('d3000000-0000-0000-0000-000000000034', 'B', 'Continue the statin at the same dose given the cardiovascular benefit outweighs symptoms', false, 'Ruled out because a significantly elevated CK with significant myalgia risks progression to rhabdomyolysis if the statin is continued unchanged, and should prompt stopping the drug.', 2),
('d3000000-0000-0000-0000-000000000034', 'C', 'Switch immediately to combination statin-fibrate therapy', false, 'Ruled out because combining a statin with a fibrate increases the risk of myopathy and is inappropriate immediately after a significant CK elevation; the statin should first be stopped and myopathy allowed to resolve.', 3),
('d3000000-0000-0000-0000-000000000034', 'D', 'Stop all lipid-lowering therapy permanently without further attempts at treatment', false, 'Ruled out because further attempts at cardiovascular risk reduction (dose adjustment, alternative statin, or non-statin agents) should be pursued rather than abandoning lipid-lowering therapy altogether.', 4),
('d3000000-0000-0000-0000-000000000034', 'E', 'Simply reduce the statin dose without stopping it, despite the significant CK elevation', false, 'Ruled out because a CK this significantly elevated with symptomatic myalgia warrants stopping the statin first, rather than continuing at a reduced dose, to avoid progression to rhabdomyolysis.', 5),
('d3000000-0000-0000-0000-000000000035', 'A', 'Switch from a statin to a fibrate', false, 'Ruled out because statins remain first-line therapy for LDL reduction in this context; a fibrate would not adequately reduce LDL to target.', 1),
('d3000000-0000-0000-0000-000000000035', 'B', 'Increase to a high-intensity statin (e.g. atorvastatin 80mg), adding ezetimibe if the target LDL is still not achieved', true, 'Correct. Patients with diabetes and multiple cardiovascular risk factors are considered high (or very high) cardiovascular risk, with correspondingly lower LDL targets. Escalating to a high-intensity statin dose is the appropriate next step to reduce LDL further, with ezetimibe added if the target is still not met on maximum tolerated statin dose.', 2),
('d3000000-0000-0000-0000-000000000035', 'C', 'Accept the current LDL as adequate since she is asymptomatic', false, 'Ruled out because her LDL remains above the recommended target for her high cardiovascular risk category, and further LDL lowering should be pursued despite the absence of symptoms.', 3),
('d3000000-0000-0000-0000-000000000035', 'D', 'Stop the statin since she has not had a prior cardiovascular event', false, 'Ruled out because statin therapy is indicated for primary prevention in high-risk patients such as those with diabetes and multiple risk factors, not only after a cardiovascular event has occurred.', 4),
('d3000000-0000-0000-0000-000000000035', 'E', 'Add niacin as the next step in therapy', false, 'Ruled out because niacin has limited evidence of cardiovascular benefit, a significant side-effect burden, and is not standard next-line therapy; increasing statin intensity (with ezetimibe if needed) is preferred.', 5),
('d3000000-0000-0000-0000-000000000036', 'A', 'A trial of a dopamine agonist first, assuming this represents a macroprolactinoma', false, 'Ruled out because the prolactin elevation here is too modest to represent a genuine macroprolactinoma of this size (which typically produces much higher levels), and represents stalk effect instead; with active visual field compromise, urgent surgical decompression is indicated rather than a medical trial.', 1),
('d3000000-0000-0000-0000-000000000036', 'B', 'Watchful waiting with a repeat MRI in six months', false, 'Ruled out because active visual field compromise from chiasmal compression is an indication for urgent, not delayed, intervention.', 2),
('d3000000-0000-0000-0000-000000000036', 'C', 'External beam radiotherapy as first-line treatment', false, 'Ruled out because radiotherapy acts slowly and is not appropriate as first-line management for acute visual field compromise, which requires urgent surgical decompression.', 3),
('d3000000-0000-0000-0000-000000000036', 'D', $x$Urgent referral for transsphenoidal surgical decompression, recognising that the modest prolactin elevation here reflects stalk compression ('stalk effect') rather than a true prolactinoma$x$, true, $x$Correct. Visual field compromise from chiasmal compression is an indication for urgent surgical decompression. The modest prolactin elevation seen here is characteristic of 'stalk effect', where compression of the pituitary stalk disrupts dopaminergic inhibition of prolactin release from surrounding normal lactotrophs; true macroprolactinomas typically cause much higher prolactin levels (often several thousand mU/L or more), so a dopamine agonist trial would not be appropriate as the primary strategy here given the visual compromise requiring urgent decompression.$x$, 4),
('d3000000-0000-0000-0000-000000000036', 'E', 'Observation alone, as visual field defects from pituitary tumours often resolve spontaneously', false, 'Ruled out because visual field defects from chiasmal compression do not reliably resolve without decompression and can progress to permanent visual loss if untreated.', 5),
('d3000000-0000-0000-0000-000000000037', 'A', 'Proceed to repeat surgery as the immediate first choice', false, 'Ruled out because the residual tumour is described as not amenable to further surgical resection, making medical therapy the appropriate next step rather than repeat surgery.', 1),
('d3000000-0000-0000-0000-000000000037', 'B', 'Start a somatostatin analogue (e.g. octreotide LAR or lanreotide)', true, 'Correct. For persistent acromegaly after surgery, a somatostatin analogue is the first-line medical therapy, reducing GH and IGF-1 levels in most patients and providing some tumour size control, and is the appropriate next step given residual, non-resectable disease.', 2),
('d3000000-0000-0000-0000-000000000037', 'C', 'Start pegvisomant as first-line therapy ahead of a somatostatin analogue trial', false, 'Ruled out because pegvisomant (a GH receptor antagonist) is typically used as second-line therapy, or added to a somatostatin analogue, when the somatostatin analogue alone provides inadequate control, rather than as the initial medical therapy.', 3),
('d3000000-0000-0000-0000-000000000037', 'D', 'Proceed directly to external beam radiotherapy, bypassing medical therapy', false, 'Ruled out because radiotherapy has a slow onset of effect (often years) and is generally reserved for cases inadequately controlled with medical therapy, not used as the immediate next step ahead of a somatostatin analogue trial.', 4),
('d3000000-0000-0000-0000-000000000037', 'E', 'Observe without treatment since surgery has already been performed', false, 'Ruled out because persistent biochemical and radiological disease after surgery requires active further treatment, given the ongoing morbidity and mortality risk of uncontrolled acromegaly.', 5),
('d3000000-0000-0000-0000-000000000038', 'A', 'Stop cabergoline once pregnancy is confirmed, monitoring clinically for symptoms of tumour growth (headache, visual disturbance) with formal visual field testing if concerns arise, rather than routine prolactin monitoring', true, 'Correct. For most microprolactinomas and macroadenomas without significant extrasellar extension, cabergoline is stopped once pregnancy is confirmed, as the risk of clinically significant tumour growth during pregnancy is low in this group. Monitoring during pregnancy relies on clinical assessment for symptoms of tumour growth, with visual field testing if there is concern, since prolactin levels rise physiologically during normal pregnancy and are not a reliable monitoring marker.', 1),
('d3000000-0000-0000-0000-000000000038', 'B', 'Continue cabergoline throughout pregnancy in all patients regardless of tumour characteristics', false, 'Ruled out because cabergoline is generally stopped once pregnancy is confirmed in patients without significant extrasellar extension, given the low risk of clinically significant growth in this group during pregnancy.', 2),
('d3000000-0000-0000-0000-000000000038', 'C', 'Check serial prolactin levels monthly throughout pregnancy to guide dosing', false, 'Ruled out because prolactin rises physiologically during normal pregnancy and is not a reliable marker for monitoring tumour behaviour; clinical assessment (and imaging/visual fields if symptomatic) is used instead.', 3),
('d3000000-0000-0000-0000-000000000038', 'D', 'Switch to bromocriptine, which should be used routinely instead of stopping treatment', false, 'Ruled out because for tumours without significant extrasellar extension, stopping dopamine agonist therapy altogether is standard practice, rather than switching agents and continuing treatment routinely.', 4),
('d3000000-0000-0000-0000-000000000038', 'E', 'Stop cabergoline and start radiotherapy prophylactically during pregnancy', false, 'Ruled out because radiotherapy is not used prophylactically during pregnancy for a prolactinoma; clinical monitoring alone is appropriate for this tumour, with treatment reinstituted only if problematic growth occurs.', 5),
('d3000000-0000-0000-0000-000000000039', 'A', 'Wait for MRI confirmation of the diagnosis before giving any treatment', false, 'Ruled out because pituitary apoplexy with hypotension is a medical emergency; empirical hydrocortisone should be given immediately on clinical suspicion, without waiting for imaging.', 1),
('d3000000-0000-0000-0000-000000000039', 'B', 'Start a dopamine agonist empirically', false, 'Ruled out because a dopamine agonist does not address the immediate life-threatening risk of acute adrenal insufficiency in apoplexy; hydrocortisone is the priority.', 2),
('d3000000-0000-0000-0000-000000000039', 'C', 'Give high-dose glucocorticoids only once a low cortisol level has been confirmed on blood testing', false, 'Ruled out because waiting for biochemical confirmation risks a dangerous delay in treatment; hydrocortisone should be given empirically based on clinical suspicion alone.', 3),
('d3000000-0000-0000-0000-000000000039', 'D', 'Treat as a migraine with analgesia and observe', false, 'Ruled out because this presentation with visual loss, ophthalmoplegia and hypotension in a patient with a known pituitary tumour is a neurosurgical and endocrine emergency, not a simple migraine.', 4),
('d3000000-0000-0000-0000-000000000039', 'E', 'Give empirical IV hydrocortisone immediately, given the risk of acute adrenal insufficiency, without waiting for imaging or cortisol results', true, 'Correct. This presentation (sudden severe headache, visual loss, ophthalmoplegia, hypotension in a patient with a known pituitary tumour) is classic for pituitary apoplexy, which can cause acute secondary adrenal insufficiency due to haemorrhage/infarction of the tumour and surrounding gland. Empirical IV hydrocortisone should be given immediately on clinical suspicion, as delaying treatment for imaging or biochemical confirmation risks a life-threatening adrenal crisis.', 5),
('d3000000-0000-0000-0000-000000000040', 'A', 'Start levothyroxine before hydrocortisone', false, 'Ruled out because this sequence risks precipitating an adrenal crisis in a glucocorticoid-deficient patient, as thyroxine increases cortisol clearance and metabolic demand.', 1),
('d3000000-0000-0000-0000-000000000040', 'B', 'Start both simultaneously, as sequence makes no clinical difference', false, 'Ruled out because the sequence is clinically important in a glucocorticoid-deficient patient; hydrocortisone must be established first to prevent adrenal crisis.', 2),
('d3000000-0000-0000-0000-000000000040', 'C', 'Start hydrocortisone before levothyroxine', true, 'Correct. Thyroxine replacement increases the metabolic clearance rate of cortisol and overall metabolic demand; in a glucocorticoid-deficient patient, starting levothyroxine before adequate glucocorticoid replacement can precipitate an acute adrenal crisis. Hydrocortisone should therefore always be established first.', 3),
('d3000000-0000-0000-0000-000000000040', 'D', 'Start desmopressin before hydrocortisone, even in a patient without diabetes insipidus', false, $x$Ruled out because there is no diabetes insipidus described here, and this option does not address the specific hydrocortisone-before-levothyroxine sequencing issue relevant to this patient's hormone replacement.$x$, 4),
('d3000000-0000-0000-0000-000000000040', 'E', 'The order of replacement therapies is not clinically significant', false, 'Ruled out because incorrect sequencing (levothyroxine before adequate glucocorticoid replacement) carries a real risk of precipitating adrenal crisis in panhypopituitarism.', 5),
('d3000000-0000-0000-0000-000000000041', 'A', 'Simple transient diabetes insipidus resolving as expected, requiring desmopressin throughout all three phases', false, 'Ruled out because the described pattern is triphasic, not simple transient DI, and giving desmopressin during the intervening SIADH-like phase would worsen hyponatraemia rather than help.', 1),
('d3000000-0000-0000-0000-000000000041', 'B', 'A classic triphasic response to pituitary stalk injury (initial transient diabetes insipidus, followed by a SIADH phase from uncontrolled ADH release by the damaged posterior pituitary causing hyponatraemia, followed by permanent diabetes insipidus); the day 5 phase should be managed with fluid restriction, not desmopressin', true, 'Correct. This triphasic pattern reflects sequential stunning, uncontrolled release, and then exhaustion of ADH-secreting neurons following stalk/posterior pituitary injury. The intervening SIADH-like phase (day 5) causes hyponatraemia and should be managed with fluid restriction; giving desmopressin at this stage would worsen the hyponatraemia by further impairing free water excretion.', 2),
('d3000000-0000-0000-0000-000000000041', 'C', 'The day 5 change represents nephrogenic diabetes insipidus requiring a thiazide diuretic', false, 'Ruled out because the fall in urine output and hyponatraemia at day 5 represents a SIADH-like phase of excess ADH release, not nephrogenic DI, which would not cause hyponatraemia in this way.', 3),
('d3000000-0000-0000-0000-000000000041', 'D', 'The hyponatraemia at day 5 should be treated with desmopressin to concentrate the urine', false, 'Ruled out because desmopressin would worsen the hyponatraemia during this SIADH-like phase; fluid restriction is the appropriate management instead.', 4),
('d3000000-0000-0000-0000-000000000041', 'E', 'The recurrence of polyuria at day 10 indicates the diabetes insipidus has fully resolved', false, 'Ruled out because recurrent polyuria at day 10 typically represents the third, often permanent, phase of diabetes insipidus following exhaustion of ADH-secreting neurons, not resolution.', 5),
('d3000000-0000-0000-0000-000000000042', 'A', 'An insulin tolerance test (or an alternative GH stimulation test, such as a glucagon test, if the insulin tolerance test is contraindicated), to formally establish the diagnosis of adult growth hormone deficiency', true, 'Correct. A low-normal IGF-1 alone is not sufficiently diagnostic of adult growth hormone deficiency, as IGF-1 can be normal despite significant GH deficiency, particularly in adults. A formal GH stimulation test (insulin tolerance test being the gold standard, with alternatives such as the glucagon stimulation test where the insulin tolerance test is contraindicated, e.g. cardiac disease or epilepsy) is required to confirm the diagnosis before committing to GH replacement therapy.', 1),
('d3000000-0000-0000-0000-000000000042', 'B', 'Start growth hormone replacement empirically based on the low-normal IGF-1 alone', false, 'Ruled out because IGF-1 alone lacks sufficient sensitivity and specificity to diagnose adult GH deficiency; formal stimulation testing is required before starting replacement therapy.', 2),
('d3000000-0000-0000-0000-000000000042', 'C', 'No further testing is needed, as the history of cranial radiotherapy alone is diagnostic of GH deficiency', false, 'Ruled out because although radiotherapy history increases pre-test probability of hypopituitarism, formal biochemical confirmation via a stimulation test is still required before diagnosing GH deficiency and starting replacement.', 3),
('d3000000-0000-0000-0000-000000000042', 'D', 'A single random growth hormone level is a sufficient diagnostic test', false, 'Ruled out because GH is secreted in a pulsatile manner, making a random level unreliable for diagnosis; a dynamic stimulation test is required.', 4),
('d3000000-0000-0000-0000-000000000042', 'E', 'Repeat pituitary MRI alone is sufficient to confirm GH deficiency', false, 'Ruled out because imaging assesses structural pituitary status but cannot confirm a functional hormone deficiency; biochemical stimulation testing is required.', 5),
('d3000000-0000-0000-0000-000000000043', 'A', 'Radioiodine is the appropriate first-line treatment regardless of her eye disease', false, 'Ruled out because radioiodine carries a recognised risk of worsening thyroid eye disease and is not the preferred first-line option in a patient with active orbitopathy.', 1),
('d3000000-0000-0000-0000-000000000043', 'B', $x$Total thyroidectomy is the appropriate first-line treatment for all newly diagnosed Graves' disease patients$x$, false, $x$Ruled out because surgery is not routine first-line therapy for Graves' disease; antithyroid drugs are the standard initial approach, with surgery reserved for specific indications.$x$, 2),
('d3000000-0000-0000-0000-000000000043', 'C', 'Propranolol alone is definitive long-term therapy', false, 'Ruled out because beta-blockers provide symptomatic control of adrenergic symptoms only and do not address the underlying hyperthyroidism; definitive therapy (antithyroid drugs, radioiodine, or surgery) is required.', 3),
('d3000000-0000-0000-0000-000000000043', 'D', 'Start an antithyroid drug (carbimazole) as first-line therapy, avoiding radioiodine as first-line treatment given her active thyroid eye disease, which risks worsening orbitopathy', true, $x$Correct. Antithyroid drug therapy (carbimazole, with propylthiouracil as an alternative particularly in early pregnancy) is appropriate first-line management for Graves' disease. Radioiodine can worsen or precipitate progression of active thyroid eye disease and is generally avoided as first-line treatment (or given with corticosteroid cover) in patients with active orbitopathy.$x$, 4),
('d3000000-0000-0000-0000-000000000043', 'E', 'No specific treatment is required since her symptoms are described as moderate', false, $x$Ruled out because Graves' disease requires active treatment to control hyperthyroidism regardless of symptom severity being described as moderate rather than severe.$x$, 5),
('d3000000-0000-0000-0000-000000000044', 'A', 'Give iodine before starting the antithyroid drug', false, 'Ruled out because giving iodine before the thionamide takes effect can transiently worsen thyrotoxicosis by providing substrate for new hormone synthesis (Jod-Basedow effect); the thionamide must be given first.', 1),
('d3000000-0000-0000-0000-000000000044', 'B', 'Carbimazole is preferred over propylthiouracil for thyroid storm', false, 'Ruled out because propylthiouracil is preferred in thyroid storm due to its additional peripheral T4-to-T3 conversion-blocking effect, which carbimazole lacks.', 2),
('d3000000-0000-0000-0000-000000000044', 'C', $x$Propranolol and propylthiouracil (preferred over carbimazole in storm for its additional peripheral T4-to-T3 conversion-blocking effect), followed at least an hour later by Lugol's iodine, together with hydrocortisone and treatment of the precipitant$x$, true, $x$Correct. Thyroid storm management includes beta-blockade for adrenergic symptoms, a thionamide (propylthiouracil is preferred over carbimazole in storm due to its additional inhibition of peripheral T4-to-T3 conversion), followed by iodine (Lugol's solution) given at least an hour after the thionamide to avoid providing substrate for new hormone synthesis before the thionamide blocks synthesis, plus hydrocortisone (which also reduces peripheral T4-to-T3 conversion and covers possible relative adrenal insufficiency) and treatment of any precipitating illness.$x$, 3),
('d3000000-0000-0000-0000-000000000044', 'D', 'Beta-blockers are contraindicated given the atrial fibrillation', false, 'Ruled out because beta-blockers are a key component of thyroid storm management, controlling adrenergic symptoms including tachyarrhythmias, and are not contraindicated by AF itself in this context (used cautiously if there is decompensated heart failure).', 4),
('d3000000-0000-0000-0000-000000000044', 'E', 'No glucocorticoid is needed as this is not primary adrenal disease', false, 'Ruled out because hydrocortisone is a standard component of thyroid storm management, both reducing peripheral T4-to-T3 conversion and covering possible relative adrenal insufficiency associated with severe thyrotoxicosis.', 5),
('d3000000-0000-0000-0000-000000000045', 'A', 'Type 1 amiodarone-induced thyrotoxicosis — managed with thionamides', false, $x$Ruled out because type 1 AIT typically occurs in a gland with underlying pathology (goitre, nodularity, or latent Graves' disease) with increased vascularity, which is not the picture described here; type 2 AIT (destructive) is more consistent with these findings and requires corticosteroids rather than thionamides.$x$, 1),
('d3000000-0000-0000-0000-000000000045', 'B', 'Stop amiodarone and no other specific treatment is required', false, 'Ruled out because while stopping amiodarone is often considered, active treatment with corticosteroids is required for type 2 AIT to control thyrotoxicosis, particularly given his significant cardiac history.', 2),
('d3000000-0000-0000-0000-000000000045', 'C', 'Radioiodine treatment is appropriate as immediate management', false, 'Ruled out because the iodine-loaded thyroid gland in amiodarone-treated patients typically has minimal radioiodine uptake, making radioiodine ineffective as acute management of AIT.', 3),
('d3000000-0000-0000-0000-000000000045', 'D', 'Additional iodine supplementation is the appropriate treatment', false, 'Ruled out because amiodarone itself is iodine-rich, and additional iodine would not treat thyrotoxicosis; corticosteroids are the appropriate treatment for the destructive process described.', 4),
('d3000000-0000-0000-0000-000000000045', 'E', 'Amiodarone-induced thyrotoxicosis type 2 (destructive thyroiditis) — managed with high-dose corticosteroids rather than thionamides', true, 'Correct. The findings of reduced thyroid vascularity on Doppler ultrasound, absence of underlying goitre/nodularity, and a raised inflammatory marker are characteristic of type 2 amiodarone-induced thyrotoxicosis, a destructive thyroiditis causing release of preformed hormone rather than increased synthesis. This is managed with high-dose corticosteroids rather than thionamides, which act on hormone synthesis and are relatively ineffective in a purely destructive process.', 5),
('d3000000-0000-0000-0000-000000000046', 'A', 'No treatment is needed since the TSH is only mildly elevated', false, 'Ruled out because in pregnancy, particularly with positive TPO antibodies, even mild TSH elevation above the trimester-specific range warrants treatment given the associated risks.', 1),
('d3000000-0000-0000-0000-000000000046', 'B', 'Treatment should only be started if TSH exceeds 10 mU/L', false, 'Ruled out because current guidance supports treating subclinical hypothyroidism in pregnancy at lower TSH thresholds than 10, especially with positive TPO antibodies present.', 2),
('d3000000-0000-0000-0000-000000000046', 'C', 'Treatment should be delayed until after the first trimester', false, 'Ruled out because early fetal neurodevelopment depends on adequate maternal thyroid hormone, particularly in the first trimester before the fetal thyroid is functional, so treatment should not be delayed.', 3),
('d3000000-0000-0000-0000-000000000046', 'D', 'Start an antithyroid drug to manage the abnormal thyroid function', false, 'Ruled out because this represents hypothyroidism (elevated TSH, low-normal T4), not thyrotoxicosis; an antithyroid drug (used for overactive thyroid) is the wrong direction of treatment entirely.', 4),
('d3000000-0000-0000-0000-000000000046', 'E', 'Start levothyroxine, titrating to trimester-specific TSH targets, given subclinical hypothyroidism with positive TPO antibodies in pregnancy', true, 'Correct. Subclinical hypothyroidism in pregnancy, particularly in the presence of positive TPO antibodies (which increases the risk of progression to overt hypothyroidism and is independently associated with adverse pregnancy outcomes), warrants treatment with levothyroxine, titrated against trimester-specific TSH targets, to reduce the risk of adverse maternal and fetal/neurodevelopmental outcomes.', 5),
('d3000000-0000-0000-0000-000000000047', 'A', 'No further treatment is required after total thyroidectomy', false, 'Ruled out because her nodal involvement places her at higher risk of recurrence, for which adjuvant radioactive iodine ablation is indicated.', 1),
('d3000000-0000-0000-0000-000000000047', 'B', 'Radioactive iodine ablation of remnant/metastatic tissue, followed by long-term levothyroxine at a TSH-suppressive dose, given her intermediate/high-risk features (nodal involvement)', true, 'Correct. Nodal involvement places her in an intermediate/high-risk category for recurrence, for whom radioactive iodine ablation after total thyroidectomy is indicated to eliminate remnant thyroid tissue and treat microscopic metastatic disease, followed by long-term levothyroxine at a TSH-suppressive (rather than simply replacement) dose to reduce the risk of TSH-driven tumour recurrence/growth.', 2),
('d3000000-0000-0000-0000-000000000047', 'C', 'Levothyroxine at a standard replacement (non-suppressive) dose is appropriate regardless of her risk category', false, 'Ruled out because intermediate/high-risk patients (such as this patient with nodal involvement) benefit from TSH-suppressive dosing to reduce recurrence risk, rather than simple replacement dosing.', 3),
('d3000000-0000-0000-0000-000000000047', 'D', 'External beam radiotherapy is routine adjuvant treatment for papillary thyroid carcinoma', false, 'Ruled out because external beam radiotherapy is not routine adjuvant treatment for differentiated thyroid cancer; radioactive iodine is the standard adjuvant modality.', 4),
('d3000000-0000-0000-0000-000000000047', 'E', 'Active surveillance without any thyroid hormone therapy is appropriate after thyroidectomy', false, 'Ruled out because after total thyroidectomy, levothyroxine replacement (and TSH suppression in higher-risk disease) is required, both for physiological hormone replacement and to reduce recurrence risk.', 5),
('d3000000-0000-0000-0000-000000000048', 'A', 'Biochemically exclude phaeochromocytoma (plasma or urine metanephrines) and arrange RET proto-oncogene genetic testing for MEN2, before any surgery', true, 'Correct. The elevated calcitonin and family history strongly suggest medullary thyroid carcinoma, which can occur as part of MEN2 syndromes associated with phaeochromocytoma. An unrecognised, unexcluded phaeochromocytoma poses a risk of catastrophic intraoperative hypertensive crisis during thyroid surgery, so biochemical exclusion is essential before proceeding, alongside RET genetic testing to confirm MEN2 and guide further family screening and management.', 1),
('d3000000-0000-0000-0000-000000000048', 'B', 'Proceed directly to total thyroidectomy without excluding phaeochromocytoma', false, 'Ruled out because operating without excluding a co-existing phaeochromocytoma risks a life-threatening intraoperative hypertensive crisis; biochemical exclusion must occur first.', 2),
('d3000000-0000-0000-0000-000000000048', 'C', 'FNA cytology alone is sufficient without calcitonin measurement or genetic workup', false, 'Ruled out because calcitonin measurement (already elevated here) and genetic workup for MEN2, along with exclusion of phaeochromocytoma, are essential in this clinical context, not FNA cytology alone.', 3),
('d3000000-0000-0000-0000-000000000048', 'D', 'Treat with radioactive iodine, as for differentiated thyroid cancer', false, 'Ruled out because medullary thyroid carcinoma arises from parafollicular (C) cells, does not take up iodine, and radioactive iodine has no role in its treatment; surgery is the primary treatment.', 4),
('d3000000-0000-0000-0000-000000000048', 'E', 'Manage with TSH suppression alone, as for papillary thyroid cancer', false, 'Ruled out because TSH-suppressive therapy is a treatment strategy for differentiated (follicular-cell-derived) thyroid cancer, not medullary thyroid carcinoma, which is not TSH-dependent.', 5),
('d3000000-0000-0000-0000-000000000049', 'A', 'Proceed directly to total thyroidectomy based on this result alone', false, 'Ruled out because Bethesda III carries a relatively low risk of malignancy and does not, on its own, warrant proceeding straight to surgery before repeat sampling or molecular testing.', 1),
('d3000000-0000-0000-0000-000000000049', 'B', 'Reassure the patient and arrange no further follow-up', false, 'Ruled out because Bethesda III is an indeterminate category requiring further evaluation (repeat FNA or molecular testing), not simple reassurance without follow-up.', 2),
('d3000000-0000-0000-0000-000000000049', 'C', 'Treat with radioactive iodine ablation without a tissue diagnosis', false, 'Ruled out because radioactive iodine ablation is a treatment for confirmed differentiated thyroid cancer after surgery, not an appropriate response to an indeterminate cytology result without a confirmed diagnosis.', 3),
('d3000000-0000-0000-0000-000000000049', 'D', 'Repeat fine needle aspiration (or consider molecular testing where available) rather than proceeding directly to diagnostic surgery', true, 'Correct. Bethesda category III carries a relatively low but not negligible risk of malignancy and is often due to sampling or interpretive limitations. Repeat FNA (or molecular testing where available, to help further risk-stratify) is the recommended next step, reserving diagnostic surgery for cases where atypia persists, molecular testing suggests higher risk, or there are other concerning clinical/radiological features.', 4),
('d3000000-0000-0000-0000-000000000049', 'E', 'Start levothyroxine at a TSH-suppressive dose as definitive management', false, 'Ruled out because TSH suppression is not an appropriate strategy for managing an indeterminate thyroid nodule and does not substitute for further diagnostic evaluation.', 5),
('d3000000-0000-0000-0000-000000000050', 'A', 'Start IV levothyroxine to correct the low free T4 acutely', false, 'Ruled out because treating sick euthyroid syndrome with thyroxine has not been shown to improve outcomes and is not standard practice; the abnormalities are expected to resolve with recovery from the underlying illness.', 1),
('d3000000-0000-0000-0000-000000000050', 'B', 'Diagnose central hypothyroidism and start replacement therapy', false, 'Ruled out because this pattern of results in the context of severe critical illness is characteristic of sick euthyroid syndrome rather than true central hypothyroidism, which should be reconsidered after recovery if abnormalities persist.', 2),
('d3000000-0000-0000-0000-000000000050', 'C', 'This is consistent with sick euthyroid syndrome (non-thyroidal illness); no thyroxine replacement is needed, and thyroid function should be reassessed after recovery from the acute illness', true, 'Correct. Sick euthyroid syndrome is a common pattern in critically unwell patients, characterised by low T3 (from reduced peripheral conversion), variably low T4, and low/low-normal TSH, without true underlying thyroid or pituitary disease. Treatment with thyroxine has not been shown to improve outcomes and is not recommended; thyroid function should be reassessed once the patient has recovered from the acute illness, as levels typically normalise.', 3),
('d3000000-0000-0000-0000-000000000050', 'D', 'Diagnose primary hypothyroidism and start high-dose levothyroxine', false, 'Ruled out because TSH is low or low-normal here (not elevated, as would be expected in primary hypothyroidism), and the pattern is consistent with sick euthyroid syndrome rather than primary thyroid failure.', 4),
('d3000000-0000-0000-0000-000000000050', 'E', 'Start an antithyroid drug given the low TSH', false, 'Ruled out because a low TSH here reflects non-thyroidal illness, not thyrotoxicosis (free T4 and T3 are low, not elevated), so an antithyroid drug is inappropriate.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('d3000000-0000-0000-0000-000000000001', 'Sick day rules (oral dose-doubling) apply only when a patient can reliably absorb oral medication; vomiting or diarrhoea mandates parenteral hydrocortisone and urgent assessment.', 1),
('d3000000-0000-0000-0000-000000000001', 'An Addisonian crisis in a patient with known adrenal insufficiency is a clinical diagnosis — treatment must not be delayed pending cortisol or electrolyte results.', 2),
('d3000000-0000-0000-0000-000000000001', 'High-dose hydrocortisone (>50mg/day) itself has sufficient mineralocorticoid activity, so fludrocortisone dose adjustment is not the acute priority during a crisis.', 3),
('d3000000-0000-0000-0000-000000000002', 'An elevated aldosterone:renin ratio is a screening test only; a confirmatory suppression test (saline infusion, fludrocortisone suppression, or captopril challenge) is required to establish autonomous aldosterone secretion.', 1),
('d3000000-0000-0000-0000-000000000002', 'Adrenal vein sampling is required before unilateral adrenalectomy in most patients, as CT alone cannot reliably distinguish a functioning unilateral adenoma from bilateral adrenal hyperplasia or a non-functioning incidentaloma.', 2),
('d3000000-0000-0000-0000-000000000002', 'Interfering antihypertensives (beta-blockers, ACE inhibitors/ARBs, mineralocorticoid receptor antagonists, high-dose diuretics) should be substituted with agents such as verapamil and doxazosin before ratio testing.', 3),
('d3000000-0000-0000-0000-000000000003', 'Alpha-blockade must always precede beta-blockade in phaeochromocytoma management to avoid unopposed alpha-adrenergic vasoconstriction and hypertensive crisis.', 1),
('d3000000-0000-0000-0000-000000000003', 'Adequate preoperative alpha-blockade (typically 1-2 weeks) with volume expansion reduces the risk of intraoperative hypertensive crisis and profound postoperative hypotension once the catecholamine-secreting tumour is removed.', 2),
('d3000000-0000-0000-0000-000000000003', 'Genetic testing (e.g. for SDHB, VHL, RET, NF1) should be considered in patients with phaeochromocytoma, particularly with young age, bilateral/multifocal disease, or a relevant family history.', 3),
('d3000000-0000-0000-0000-000000000004', $x$An undetectable postoperative cortisol after transsphenoidal surgery for Cushing's disease is the expected marker of surgical remission, reflecting suppression of normal corticotrophs by preceding endogenous hypercortisolism.$x$, 1),
('d3000000-0000-0000-0000-000000000004', 'Physiological hydrocortisone replacement is required after cure and weaned gradually, with HPA axis recovery assessed periodically over the following months to a year.', 2),
('d3000000-0000-0000-0000-000000000004', 'Persistently normal or elevated postoperative cortisol suggests residual or recurrent disease and should prompt further biochemical and imaging evaluation.', 3),
('d3000000-0000-0000-0000-000000000005', 'Mineralocorticoid receptor antagonists (spironolactone, eplerenone) are the mainstay of both interim preoperative and definitive medical management of primary hyperaldosteronism.', 1),
('d3000000-0000-0000-0000-000000000005', 'Unilateral adrenalectomy is curative for hypokalaemia in most patients with a lateralised aldosterone-producing adenoma, and often improves or cures hypertension, though longstanding hypertension may not fully resolve.', 2),
('d3000000-0000-0000-0000-000000000005', 'Blood pressure and potassium should be optimised medically before surgery to reduce perioperative risk.', 3),
('d3000000-0000-0000-0000-000000000006', 'Hydrocortisone is inactivated by placental 11-beta-HSD2 and is the preferred glucocorticoid for maternal replacement in pregnancy; dexamethasone crosses the placenta and is reserved for specific fetal-directed indications.', 1),
('d3000000-0000-0000-0000-000000000006', 'Monitoring in pregnant women with CAH relies on clinical assessment rather than 17-hydroxyprogesterone, which is not a validated target in pregnancy.', 2),
('d3000000-0000-0000-0000-000000000006', 'Stress-dose glucocorticoid cover is required for labour and delivery, analogous to other major physiological stress in adrenal insufficiency/CAH.', 3),
('d3000000-0000-0000-0000-000000000007', $x$Mild autonomous cortisol secretion describes non-suppressible cortisol on a 1mg dexamethasone suppression test without overt clinical Cushingoid features, and is managed differently from frank Cushing's syndrome.$x$, 1),
('d3000000-0000-0000-0000-000000000007', 'Management decisions in adrenal incidentalomas with mild autonomous cortisol secretion hinge on the presence and severity of associated comorbidities (hypertension, diabetes, osteoporosis) rather than biochemistry alone.', 2),
('d3000000-0000-0000-0000-000000000007', 'All adrenal incidentalomas require assessment for both malignant potential (imaging characteristics, size, growth) and hormonal function (cortisol, aldosterone if hypertensive/hypokalaemic, metanephrines).', 3),
('d3000000-0000-0000-0000-000000000008', 'Criteria for parathyroidectomy in asymptomatic primary hyperparathyroidism include reduced eGFR (<60), significantly elevated calcium, osteoporosis or fragility fracture, and age under 50 — meeting any one criterion is sufficient.', 1),
('d3000000-0000-0000-0000-000000000008', 'Parathyroidectomy is curative in primary hyperparathyroidism and is preferred over long-term medical management once surgical criteria are met.', 2),
('d3000000-0000-0000-0000-000000000008', 'Conservative monitoring with annual calcium, renal function and periodic DEXA is appropriate only for patients who do not meet any surgical criterion.', 3),
('d3000000-0000-0000-0000-000000000009', 'Bisphosphonates (e.g. zoledronic acid) are relatively contraindicated in significant renal impairment; denosumab is preferred as it is not renally cleared.', 1),
('d3000000-0000-0000-0000-000000000009', 'IV rehydration with 0.9% saline is the essential first step in managing severe hypercalcaemia, correcting volume depletion and improving renal calcium excretion before definitive calcium-lowering therapy.', 2),
('d3000000-0000-0000-0000-000000000009', 'Calcitonin provides rapid but short-lived calcium lowering due to tachyphylaxis and is used as a bridge while awaiting the slower onset of bisphosphonate/denosumab effect.', 3),
('d3000000-0000-0000-0000-000000000010', 'Atypical femoral fractures are a recognised complication of prolonged bisphosphonate therapy, characterised by prodromal thigh/groin pain and radiographic lateral cortical thickening/beaking before a completed transverse fracture occurs.', 1),
('d3000000-0000-0000-0000-000000000010', $x$A 'bisphosphonate holiday' is considered after prolonged therapy (typically 5-10 years) once substantial fracture risk reduction has been achieved, particularly in lower-risk patients, balancing ongoing fracture prevention against rare long-term risks such as atypical fracture and osteonecrosis of the jaw.$x$, 2),
('d3000000-0000-0000-0000-000000000010', 'Suspected atypical femoral fracture warrants stopping the bisphosphonate, non-weight-bearing precautions, and orthopaedic assessment for prophylactic fixation given the high risk of progression to a completed fracture.', 3),
('d3000000-0000-0000-0000-000000000011', 'Post-surgical hypoparathyroidism causes hypocalcaemia via PTH deficiency and requires active vitamin D analogues (alfacalcidol/calcitriol) rather than native vitamin D, because renal 1-hydroxylation is PTH-dependent.', 1),
('d3000000-0000-0000-0000-000000000011', 'Symptomatic severe hypocalcaemia (tetany, seizures, prolonged QT) requires urgent IV calcium gluconate replacement.', 2),
('d3000000-0000-0000-0000-000000000011', $x$Long-term management targets a low-normal serum calcium (avoiding hypercalciuria and nephrocalcinosis, since PTH's renal calcium-conserving effect is absent) with regular monitoring of calcium and renal function.$x$, 3),
('d3000000-0000-0000-0000-000000000012', 'Osteomalacia presents with bone pain, proximal myopathy, low vitamin D, and characteristically Looser zones (pseudofractures) on imaging, distinguishing it from osteoporosis.', 1),
('d3000000-0000-0000-0000-000000000012', 'Vitamin D deficiency should be corrected with a loading regimen before considering other bone-active therapies, as untreated deficiency increases fracture risk with bisphosphonate use and can cause severe hypocalcaemia if unrecognised.', 2),
('d3000000-0000-0000-0000-000000000012', $x$Elevated ALP with low/low-normal calcium and low vitamin D points towards osteomalacia rather than primary hyperparathyroidism (typically elevated calcium) or Paget's disease (typically normal calcium/vitamin D with focal skeletal disease).$x$, 3),
('d3000000-0000-0000-0000-000000000013', $x$Indications for treating Paget's disease include bone pain, hypercalcaemia (rare), neurological complications, high-output cardiac failure, and preparation before surgery on affected bone.$x$, 1),
('d3000000-0000-0000-0000-000000000013', $x$IV zoledronic acid is highly effective at achieving prolonged biochemical and symptomatic remission in Paget's disease.$x$, 2),
('d3000000-0000-0000-0000-000000000013', 'Pretreatment with a bisphosphonate before orthopaedic surgery on Pagetic bone reduces vascularity and intraoperative blood loss.', 3),
('d3000000-0000-0000-0000-000000000014', 'Familial hypocalciuric hypercalcaemia is caused by inactivating calcium-sensing receptor mutations and should be distinguished from primary hyperparathyroidism using a 24-hour urine calcium:creatinine clearance ratio (low, typically <0.01, in FHH).', 1),
('d3000000-0000-0000-0000-000000000014', 'Parathyroidectomy does not correct FHH, as the defect lies in receptor-level calcium sensing rather than autonomous parathyroid hormone secretion, and unnecessary surgery should be avoided.', 2),
('d3000000-0000-0000-0000-000000000014', 'A family history of mild, lifelong, asymptomatic hypercalcaemia is an important clue pointing away from primary hyperparathyroidism towards FHH.', 3),
('d3000000-0000-0000-0000-000000000015', 'SGLT2 inhibitors reduce heart failure hospitalisation and cardiovascular mortality in type 2 diabetes with heart failure with reduced ejection fraction, independent of glycaemic control.', 1),
('d3000000-0000-0000-0000-000000000015', 'Pioglitazone is contraindicated in heart failure due to fluid retention.', 2),
('d3000000-0000-0000-0000-000000000015', 'Choice of second/third-line glucose-lowering therapy in type 2 diabetes should be guided by cardiorenal comorbidity, not glycaemic efficacy alone.', 3),
('d3000000-0000-0000-0000-000000000016', 'Metformin should be stopped or significantly dose-reduced as eGFR falls below approximately 30-45 mL/min/1.73m2 due to lactic acidosis risk.', 1),
('d3000000-0000-0000-0000-000000000016', 'SGLT2 inhibitors have specific renal-protective benefits in diabetic kidney disease (reducing proteinuria and progression to end-stage renal disease) and can be used down to low eGFR thresholds per current guidance.', 2),
('d3000000-0000-0000-0000-000000000016', 'Glycaemic management in advanced CKD often requires insulin once oral agent options become limited by renal function.', 3),
('d3000000-0000-0000-0000-000000000017', 'Recurrent severe hypoglycaemia with impaired awareness is a key indication for continuous glucose monitoring and, where appropriate, hybrid closed-loop insulin pump therapy.', 1),
('d3000000-0000-0000-0000-000000000017', 'Structured education (e.g. avoiding stacking insulin, recognising early warning patterns) combined with technology can help restore hypoglycaemia awareness over time.', 2),
('d3000000-0000-0000-0000-000000000017', 'Islet cell or pancreas transplantation is reserved for selected cases of severe, refractory hypoglycaemia unresponsive to optimised medical/technological management.', 3),
('d3000000-0000-0000-0000-000000000018', 'GLP-1 receptor agonists reduce major adverse cardiovascular events in type 2 diabetes with established atherosclerotic cardiovascular disease, alongside significant weight loss benefit.', 1),
('d3000000-0000-0000-0000-000000000018', 'Choice of add-on diabetes therapy in high cardiovascular risk patients should prioritise agents with proven cardiovascular outcome benefit (SGLT2 inhibitors, GLP-1 receptor agonists) over agents with neutral or adverse cardiovascular profiles.', 2),
('d3000000-0000-0000-0000-000000000018', 'Combining a DPP-4 inhibitor with a GLP-1 receptor agonist is not recommended, as both act on the incretin pathway with no additive benefit.', 3),
('d3000000-0000-0000-0000-000000000019', 'Insulin resistance increases progressively through pregnancy (particularly second and third trimesters) due to placental hormones, so insulin doses typically need to increase substantially as pregnancy advances.', 1),
('d3000000-0000-0000-0000-000000000019', 'Pregnancy-specific glucose targets are tighter than standard non-pregnant targets, reflecting the goal of minimising risks such as macrosomia and other adverse fetal outcomes.', 2),
('d3000000-0000-0000-0000-000000000019', 'Continuous glucose monitoring is recommended in pregnant women with type 1 diabetes to support tight glycaemic control and timely insulin titration.', 3),
('d3000000-0000-0000-0000-000000000020', 'Finerenone, a non-steroidal mineralocorticoid receptor antagonist, reduces chronic kidney disease progression and cardiovascular events when added to an ACE inhibitor/ARB and SGLT2 inhibitor in diabetic kidney disease with persistent albuminuria.', 1),
('d3000000-0000-0000-0000-000000000020', 'Finerenone carries a lower risk of hyperkalaemia and gynaecomastia compared with older steroidal mineralocorticoid receptor antagonists such as spironolactone.', 2),
('d3000000-0000-0000-0000-000000000020', 'Multi-drug renoprotective strategies (RAAS blockade, SGLT2 inhibition, and now non-steroidal MRA therapy) act on complementary pathways and are increasingly combined in diabetic kidney disease.', 3),
('d3000000-0000-0000-0000-000000000021', 'MODY should be suspected with negative islet autoantibodies, preserved C-peptide years after diagnosis, lean body habitus, and a strong multi-generational family history suggesting autosomal dominant inheritance.', 1),
('d3000000-0000-0000-0000-000000000021', 'HNF1A-MODY (and HNF4A-MODY) are characteristically sensitive to sulfonylureas, which can often replace insulin therapy and achieve superior glycaemic control once the diagnosis is genetically confirmed.', 2),
('d3000000-0000-0000-0000-000000000021', 'Correctly distinguishing MODY from type 1 or type 2 diabetes has major treatment, prognostic and family screening implications.', 3),
('d3000000-0000-0000-0000-000000000022', 'A fixed-rate intravenous insulin infusion is started promptly in DKA alongside fluid resuscitation, without waiting for potassium to normalise.', 1),
('d3000000-0000-0000-0000-000000000022', 'Potassium is withheld from initial fluids only while serum potassium remains above 5.5 mmol/L; it typically falls once insulin therapy begins and must be closely monitored and replaced accordingly.', 2),
('d3000000-0000-0000-0000-000000000022', 'An initial insulin bolus is not part of standard DKA management; a fixed-rate infusion is used from the outset.', 3),
('d3000000-0000-0000-0000-000000000023', 'DKA resolution is defined biochemically (typically pH >7.3, bicarbonate >18, ketones <0.6 mmol/L) rather than by glucose level alone.', 1),
('d3000000-0000-0000-0000-000000000023', 'Transition from IV to subcutaneous insulin requires an overlap period (usually 1-2 hours) after subcutaneous insulin is given before stopping the IV infusion, to avoid a gap in insulin coverage.', 2),
('d3000000-0000-0000-0000-000000000023', 'Basal insulin should be part of the subcutaneous regimen established at transition, not just short-acting insulin with meals, to prevent rebound hyperglycaemia/ketosis between meals.', 3),
('d3000000-0000-0000-0000-000000000024', 'HHS is managed with cautious rehydration as the primary therapy; rapid correction of glucose/osmolality risks dangerous osmotic complications including cerebral oedema and central pontine myelinolysis.', 1),
('d3000000-0000-0000-0000-000000000024', 'Insulin is used at a lower rate (or withheld initially) in HHS compared with DKA, since fluids alone often substantially reduce glucose, and insulin can precipitate too rapid an osmotic shift.', 2),
('d3000000-0000-0000-0000-000000000024', 'HHS characteristically presents with marked hyperglycaemia and hyperosmolality without significant ketosis or acidosis, distinguishing it from DKA (though mixed DKA/HHS pictures occur).', 3),
('d3000000-0000-0000-0000-000000000025', 'SGLT2 inhibitors can precipitate euglycaemic DKA, where significant acidosis and ketosis occur despite only mildly elevated or near-normal glucose, due to enhanced renal glucose excretion.', 1),
('d3000000-0000-0000-0000-000000000025', 'Management of euglycaemic DKA follows standard DKA principles (IV insulin to suppress ketogenesis) but requires concurrent dextrose infusion to avoid hypoglycaemia while adequate insulin is administered.', 2),
('d3000000-0000-0000-0000-000000000025', $x$SGLT2 inhibitors should be stopped during an episode of DKA and any acute illness with risk of dehydration/reduced oral intake ('sick day rules'), given this recognised risk.$x$, 3),
('d3000000-0000-0000-0000-000000000026', 'Intramuscular glucagon is the appropriate immediate treatment for severe hypoglycaemia with reduced consciousness when IV access is not available, and can be administered by trained family members/carers.', 1),
('d3000000-0000-0000-0000-000000000026', 'Oral treatment should never be given to an unconscious patient due to aspiration risk; treatment must be via a parenteral route until consciousness and safe swallow return.', 2),
('d3000000-0000-0000-0000-000000000026', 'Once conscious, patients should take oral carbohydrate (both fast- and longer-acting) to prevent recurrence of hypoglycaemia after glucagon or IV dextrose wears off.', 3),
('d3000000-0000-0000-0000-000000000027', 'Sulfonylurea-induced hypoglycaemia, particularly with long-acting agents in elderly or renally impaired patients, can be severe, prolonged and recurrent, requiring admission for extended monitoring, not a single treatment and discharge.', 1),
('d3000000-0000-0000-0000-000000000027', 'Octreotide suppresses sulfonylurea-stimulated pancreatic insulin release and can be used for hypoglycaemia refractory to dextrose alone.', 2),
('d3000000-0000-0000-0000-000000000027', 'Repeated glucagon is not an effective long-term strategy for recurrent hypoglycaemia due to depletion of hepatic glycogen stores with repeated use.', 3),
('d3000000-0000-0000-0000-000000000028', 'Headache, reduced conscious level and bradycardia during DKA treatment (particularly in children and young people) are classic warning signs of cerebral oedema and require immediate action, not observation.', 1),
('d3000000-0000-0000-0000-000000000028', 'Management of suspected cerebral oedema includes slowing/stopping IV fluids, giving hyperosmolar therapy (mannitol or hypertonic saline), and urgent senior/critical care involvement, with imaging performed once the patient is stabilised rather than delaying treatment for confirmation.', 2),
('d3000000-0000-0000-0000-000000000028', 'Children and young people with DKA are at particularly increased risk of cerebral oedema compared with adults, and fluid resuscitation protocols in paediatric DKA are more cautious for this reason.', 3),
('d3000000-0000-0000-0000-000000000029', 'Familial hypercholesterolaemia can be diagnosed clinically using validated criteria (e.g. Dutch Lipid Clinic Network) combining LDL level, physical signs (xanthomas/xanthelasma), and family history, without requiring genetic confirmation before starting treatment.', 1),
('d3000000-0000-0000-0000-000000000029', 'Cascade testing of first-degree relatives is a core part of managing familial hypercholesterolaemia, given its autosomal dominant inheritance and the value of early detection/treatment.', 2),
('d3000000-0000-0000-0000-000000000029', 'High-intensity statin therapy, with ezetimibe added if LDL targets are not achieved, is first-line pharmacological management.', 3),
('d3000000-0000-0000-0000-000000000030', 'PCSK9 inhibitors provide substantial additional LDL lowering and reduce cardiovascular events when added to maximum tolerated statin plus ezetimibe in patients with residual risk, particularly in secondary prevention.', 1),
('d3000000-0000-0000-0000-000000000030', 'Fibrates have only a modest LDL-lowering effect and are used primarily for hypertriglyceridaemia rather than to further reduce LDL in patients already on statin/ezetimibe therapy.', 2),
('d3000000-0000-0000-0000-000000000030', 'Treatment escalation decisions in lipid management should be guided by cardiovascular risk category and specific LDL targets, which are lower for secondary prevention/very high-risk patients.', 3),
('d3000000-0000-0000-0000-000000000031', 'IV insulin infusion (with dextrose) is an effective acute treatment for severe hypertriglyceridaemia by accelerating lipoprotein lipase-mediated triglyceride clearance, and is used in hypertriglyceridaemia-induced pancreatitis.', 1),
('d3000000-0000-0000-0000-000000000031', 'Plasmapheresis is reserved for cases with organ failure or where insulin infusion and supportive measures are inadequate or contraindicated.', 2),
('d3000000-0000-0000-0000-000000000031', 'Long-term management of severe hypertriglyceridaemia (fibrate therapy, dietary fat restriction, addressing secondary causes such as poorly controlled diabetes or alcohol) is essential to prevent recurrent pancreatitis.', 3),
('d3000000-0000-0000-0000-000000000032', 'Familial combined hyperlipidaemia is characterised by a variable lipid phenotype within affected families and is one of the more common inherited causes of premature coronary heart disease.', 1),
('d3000000-0000-0000-0000-000000000032', 'Management of familial combined hyperlipidaemia is tailored to the predominant lipid abnormality, often combining a statin with a fibrate or addressing triglycerides and LDL as needed.', 2),
('d3000000-0000-0000-0000-000000000032', 'Distinguishing familial combined hyperlipidaemia from familial hypercholesterolaemia matters because of differing phenotypic patterns, though both carry significantly increased cardiovascular risk warranting active treatment.', 3),
('d3000000-0000-0000-0000-000000000033', 'Homozygous familial hypercholesterolaemia typically has minimal or absent LDL receptor function, resulting in a poor response to standard oral/injectable lipid-lowering therapies that act via receptor upregulation.', 1),
('d3000000-0000-0000-0000-000000000033', 'LDL apheresis is required in homozygous FH to achieve adequate LDL reduction, used in addition to maximal pharmacological therapy (statin, ezetimibe, PCSK9 inhibitor, and where available, newer agents such as lomitapide or evinacumab).', 2),
('d3000000-0000-0000-0000-000000000033', 'Homozygous FH causes accelerated atherosclerosis from early childhood, and aggressive treatment should begin as early as possible to reduce the very high lifetime cardiovascular risk.', 3),
('d3000000-0000-0000-0000-000000000034', 'Significant creatine kinase elevation with myalgia on a statin warrants stopping the drug to prevent progression to rhabdomyolysis, followed by cautious rechallenge once resolved.', 1),
('d3000000-0000-0000-0000-000000000034', 'Statin intolerance can often be managed with dose reduction, alternate-day dosing, or switching to a different statin, before resorting to non-statin agents such as ezetimibe or PCSK9 inhibitors.', 2),
('d3000000-0000-0000-0000-000000000034', 'Combining a statin with a fibrate (particularly gemfibrozil) increases myopathy risk and should be approached cautiously, especially soon after an episode of significant CK elevation.', 3),
('d3000000-0000-0000-0000-000000000035', 'Patients with diabetes and additional cardiovascular risk factors are classified as high or very high cardiovascular risk, with correspondingly lower LDL-cholesterol targets guiding treatment intensity.', 1),
('d3000000-0000-0000-0000-000000000035', 'Statin therapy is indicated for primary prevention in high-risk patients (such as those with diabetes and multiple risk factors), not reserved only for secondary prevention after an event.', 2),
('d3000000-0000-0000-0000-000000000035', 'Ezetimibe is added to statin therapy when LDL targets are not achieved on maximum tolerated statin dose alone.', 3),
('d3000000-0000-0000-0000-000000000036', $x$'Stalk effect' causes a modest prolactin elevation (typically well below levels seen with true macroprolactinomas) due to disrupted dopaminergic inhibition from pituitary stalk compression, and should be distinguished from a genuine prolactinoma.$x$, 1),
('d3000000-0000-0000-0000-000000000036', 'Visual field compromise from chiasmal compression by a pituitary macroadenoma is an indication for urgent surgical decompression, regardless of modest hormonal abnormalities that may be due to stalk effect.', 2),
('d3000000-0000-0000-0000-000000000036', 'True macroprolactinomas typically produce very high serum prolactin levels; a mismatch between tumour size and modest prolactin elevation should raise suspicion of stalk effect rather than a functioning prolactinoma.', 3),
('d3000000-0000-0000-0000-000000000037', 'Somatostatin analogues (octreotide, lanreotide) are first-line medical therapy for persistent acromegaly after surgery, reducing GH/IGF-1 in most patients.', 1),
('d3000000-0000-0000-0000-000000000037', 'Pegvisomant, a GH receptor antagonist, is generally used as second-line therapy (alone or combined with a somatostatin analogue) when somatostatin analogue therapy alone is inadequate.', 2),
('d3000000-0000-0000-0000-000000000037', 'External beam radiotherapy has a slow onset of biochemical effect and is generally reserved for disease inadequately controlled by surgery and medical therapy.', 3),
('d3000000-0000-0000-0000-000000000038', 'Dopamine agonist therapy for prolactinoma is generally stopped once pregnancy is confirmed in patients without significant extrasellar tumour extension, given the low risk of clinically significant growth during pregnancy in this group.', 1),
('d3000000-0000-0000-0000-000000000038', 'Prolactin levels are not a reliable monitoring tool during pregnancy as they rise physiologically; monitoring relies on clinical symptoms of tumour growth, with visual field testing if these develop.', 2),
('d3000000-0000-0000-0000-000000000038', 'Larger macroadenomas with significant suprasellar/parasellar extension may warrant continuing dopamine agonist therapy through pregnancy or closer surveillance, reflecting a higher risk of clinically significant growth.', 3),
('d3000000-0000-0000-0000-000000000039', 'Pituitary apoplexy presents with sudden severe headache, visual loss/field defects, ophthalmoplegia, and can cause life-threatening acute secondary adrenal insufficiency.', 1),
('d3000000-0000-0000-0000-000000000039', 'Empirical IV hydrocortisone should be given immediately on clinical suspicion of pituitary apoplexy, without waiting for imaging or biochemical confirmation, given the risk of adrenal crisis.', 2),
('d3000000-0000-0000-0000-000000000039', 'Definitive management of pituitary apoplexy (surgical decompression versus conservative management) depends on the severity of visual/neurological compromise and clinical trajectory.', 3),
('d3000000-0000-0000-0000-000000000040', 'In panhypopituitarism, hydrocortisone replacement must always be established before starting levothyroxine, since thyroxine increases cortisol clearance and metabolic demand and can precipitate adrenal crisis in a glucocorticoid-deficient patient.', 1),
('d3000000-0000-0000-0000-000000000040', 'Patients with combined ACTH and TSH deficiency are at particular risk of this complication if replacement therapy is started in the wrong order.', 2),
('d3000000-0000-0000-0000-000000000040', 'Similarly, if diabetes insipidus coexists with cortisol deficiency, hydrocortisone should generally be established before desmopressin, as glucocorticoid deficiency itself can mask the severity of diabetes insipidus (impairing free water clearance).', 3),
('d3000000-0000-0000-0000-000000000041', 'The triphasic response after pituitary stalk injury comprises initial transient diabetes insipidus, an intervening SIADH-like phase (from uncontrolled ADH release by the dying posterior pituitary), and then permanent diabetes insipidus.', 1),
('d3000000-0000-0000-0000-000000000041', 'The intervening SIADH-like phase should be managed with fluid restriction; giving desmopressin at this stage risks worsening hyponatraemia.', 2),
('d3000000-0000-0000-0000-000000000041', 'Close monitoring of fluid balance, sodium and urine output is essential after pituitary surgery to detect and correctly manage each phase of this evolving pattern.', 3),
('d3000000-0000-0000-0000-000000000042', 'IGF-1 alone is not sufficiently sensitive or specific to diagnose adult growth hormone deficiency; formal GH stimulation testing (insulin tolerance test being the gold standard) is required.', 1),
('d3000000-0000-0000-0000-000000000042', 'The insulin tolerance test is contraindicated in patients with cardiac disease or epilepsy, in whom alternative stimulation tests such as the glucagon test are used instead.', 2),
('d3000000-0000-0000-0000-000000000042', 'A history of cranial irradiation, pituitary surgery, or structural pituitary/hypothalamic disease increases the pre-test probability of GH deficiency but does not replace the need for biochemical confirmation before starting replacement therapy.', 3),
('d3000000-0000-0000-0000-000000000043', 'Radioiodine therapy carries a recognised risk of worsening thyroid eye disease and is generally avoided as first-line treatment (or given with corticosteroid prophylaxis) in patients with active orbitopathy.', 1),
('d3000000-0000-0000-0000-000000000043', $x$Antithyroid drugs (carbimazole, or propylthiouracil in early pregnancy) are standard first-line therapy for Graves' disease.$x$, 2),
('d3000000-0000-0000-0000-000000000043', $x$The choice between antithyroid drugs, radioiodine and surgery in Graves' disease should take into account the presence and activity of thyroid eye disease, alongside other factors such as goitre size, pregnancy plans, and patient preference.$x$, 3),
('d3000000-0000-0000-0000-000000000044', 'Propylthiouracil is preferred over carbimazole in thyroid storm due to its additional inhibitory effect on peripheral T4-to-T3 conversion.', 1),
('d3000000-0000-0000-0000-000000000044', $x$Iodine (Lugol's solution) should be given at least an hour after the thionamide in thyroid storm, to avoid providing substrate for new hormone synthesis before synthesis is blocked.$x$, 2),
('d3000000-0000-0000-0000-000000000044', 'Hydrocortisone is a standard component of thyroid storm management, reducing peripheral conversion of T4 to T3 and covering possible relative adrenal insufficiency.', 3),
('d3000000-0000-0000-0000-000000000045', 'Type 2 amiodarone-induced thyrotoxicosis is a destructive thyroiditis, characterised by reduced vascularity on Doppler ultrasound and typically responds to high-dose corticosteroids rather than thionamides.', 1),
('d3000000-0000-0000-0000-000000000045', $x$Type 1 amiodarone-induced thyrotoxicosis occurs in a gland with underlying pathology (nodularity, goitre or latent Graves' disease), shows increased vascularity, and is managed with thionamides (sometimes at higher doses, given the iodine-replete gland).$x$, 2),
('d3000000-0000-0000-0000-000000000045', 'Radioiodine is typically ineffective in AIT due to iodine loading from amiodarone suppressing thyroidal radioiodine uptake, limiting its acute utility.', 3),
('d3000000-0000-0000-0000-000000000046', 'Subclinical hypothyroidism in pregnancy with positive TPO antibodies warrants treatment with levothyroxine given the risk of progression and adverse pregnancy/neurodevelopmental outcomes.', 1),
('d3000000-0000-0000-0000-000000000046', 'TSH targets in pregnancy are trimester-specific and generally lower than standard non-pregnant reference ranges.', 2),
('d3000000-0000-0000-0000-000000000046', 'Adequate maternal thyroid hormone is particularly important in early pregnancy, before the fetal thyroid becomes functional, making early treatment important rather than delaying to later trimesters.', 3),
('d3000000-0000-0000-0000-000000000047', 'Radioactive iodine ablation after total thyroidectomy is indicated in intermediate/high-risk differentiated thyroid cancer (e.g. with nodal involvement, larger tumour size, or extrathyroidal extension) to eliminate remnant tissue and treat microscopic disease.', 1),
('d3000000-0000-0000-0000-000000000047', 'TSH-suppressive levothyroxine dosing (rather than standard replacement dosing) is used in higher-risk differentiated thyroid cancer to reduce the risk of TSH-driven recurrence, balanced against the risks of iatrogenic thyrotoxicosis.', 2),
('d3000000-0000-0000-0000-000000000047', 'Risk stratification (tumour size, histological subtype, extrathyroidal extension, nodal/distant metastasis) guides the intensity of adjuvant therapy in differentiated thyroid cancer.', 3),
('d3000000-0000-0000-0000-000000000048', 'Phaeochromocytoma must be biochemically excluded before any surgery in a patient with suspected medullary thyroid carcinoma and a relevant family history, given the risk of catastrophic intraoperative hypertensive crisis if unrecognised.', 1),
('d3000000-0000-0000-0000-000000000048', 'Medullary thyroid carcinoma arises from parafollicular C cells, secretes calcitonin (a useful tumour marker), and can occur as part of MEN2 syndromes associated with phaeochromocytoma and primary hyperparathyroidism.', 2),
('d3000000-0000-0000-0000-000000000048', 'RET proto-oncogene genetic testing is important in suspected or confirmed medullary thyroid carcinoma to identify MEN2 and guide family screening, as medullary thyroid carcinoma does not respond to radioactive iodine or TSH suppression, unlike differentiated thyroid cancers.', 3),
('d3000000-0000-0000-0000-000000000049', 'The Bethesda classification system stratifies thyroid FNA cytology into categories with associated malignancy risk, guiding management from repeat FNA/surveillance through to diagnostic or therapeutic surgery.', 1),
('d3000000-0000-0000-0000-000000000049', 'Bethesda III (atypia of undetermined significance) carries a relatively low malignancy risk and is typically managed with repeat FNA or molecular testing rather than immediate surgery.', 2),
('d3000000-0000-0000-0000-000000000049', 'Molecular testing of indeterminate thyroid nodules can help further risk-stratify patients, reducing unnecessary diagnostic surgery for nodules likely to be benign.', 3),
('d3000000-0000-0000-0000-000000000050', 'Sick euthyroid syndrome (non-thyroidal illness) commonly occurs in critically unwell patients, with low T3, variably low T4, and low/low-normal TSH, without true thyroid or pituitary pathology.', 1),
('d3000000-0000-0000-0000-000000000050', 'Thyroid hormone replacement in sick euthyroid syndrome has not been shown to improve outcomes and is not recommended; thyroid function tests should be reassessed after recovery from the acute illness.', 2),
('d3000000-0000-0000-0000-000000000050', 'Interpreting thyroid function tests during acute severe illness requires caution, as the pattern can mimic central hypothyroidism; retesting after recovery clarifies the true underlying thyroid status.', 3);
